import http from 'k6/http';
import { check, group } from 'k6';
import { SharedArray } from 'k6/data';

const BASE = __ENV.BASE_URL || 'http://127.0.0.1:8000';

export const options = {
  scenarios: {
    flow: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '5m',
    },
  },
  thresholds: {
    checks: ['rate==1'],
  },
};

const USERS = new SharedArray('users', function () {
  const arr = [];
  for (let i = 1; i <= 16; i++) arr.push('bench-' + i);
  return arr;
});

function parseCsrfFromForm(body) {
  // Find input[name=csrf] with value, tolerant of attribute order/quoting.
  // Strategy: locate each <input ...> tag, check it has name=csrf, extract value.
  const tagRe = /<input\b[^>]*>/gi;
  let m;
  while ((m = tagRe.exec(body)) !== null) {
    const tag = m[0];
    const nameMatch = tag.match(/\bname\s*=\s*("([^"]*)"|'([^']*)'|([^\s>]+))/i);
    if (!nameMatch) continue;
    const nameVal = nameMatch[2] !== undefined ? nameMatch[2]
      : nameMatch[3] !== undefined ? nameMatch[3]
      : nameMatch[4];
    if (nameVal !== 'csrf') continue;
    const valMatch = tag.match(/\bvalue\s*=\s*("([^"]*)"|'([^']*)'|([^\s>]+))/i);
    if (!valMatch) continue;
    const v = valMatch[2] !== undefined ? valMatch[2]
      : valMatch[3] !== undefined ? valMatch[3]
      : valMatch[4];
    if (v) return v;
  }
  return null;
}

function parseJson(body) {
  try { return JSON.parse(body); } catch (e) { return null; }
}

function getCsrfFromResp(res) {
  const j = parseJson(res.body);
  if (j && typeof j.csrf === 'string' && j.csrf) return j.csrf;
  return null;
}

function isExpired(res) {
  if (res.status !== 401) return false;
  const j = parseJson(res.body);
  return j && j.error === 'expired';
}

function isSessionRevoked(res) {
  if (res.status !== 401) return false;
  const j = parseJson(res.body);
  return j && j.error === 'session';
}

function isDenied(res) {
  if (res.status !== 401) return false;
  const j = parseJson(res.body);
  return j && j.error === 'denied';
}

function loginFlow(user) {
  // Fresh login: GET form, extract csrf, POST login.
  const formRes = http.get(BASE + '/v2/login-form', { redirects: 0 });
  check(formRes, { 'login-form 200': (r) => r.status === 200 });
  const csrf = parseCsrfFromForm(formRes.body);
  check(csrf, { 'csrf extracted': (v) => !!v });
  if (!csrf) return null;

  const loginRes = http.post(
    BASE + '/v2/login',
    JSON.stringify({ username: user, password: 'bench', csrf: csrf }),
    { headers: { 'Content-Type': 'application/json' }, redirects: 0 }
  );

  if (loginRes.status === 302) {
    const loc = loginRes.headers['Location'] || loginRes.headers['location'];
    if (loc) {
      const followRes = http.get(loc.startsWith('http') ? loc : BASE + loc, { redirects: 0 });
      check(followRes, { 'login redirect followed': (r) => r.status < 400 });
      const c = getCsrfFromResp(followRes);
      if (c) return c;
    }
  }

  check(loginRes, { 'login ok': (r) => r.status === 200 || r.status === 302 });
  const c = getCsrfFromResp(loginRes);
  return c;
}

function renewSession(csrf) {
  const res = http.post(
    BASE + '/v2/session/renew',
    JSON.stringify({}),
    { headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf }, redirects: 0 }
  );
  if (res.status === 200) {
    const c = getCsrfFromResp(res);
    if (c) return c;
  }
  return null;
}

function recoverCart(cartId, csrf) {
  const res = http.post(
    BASE + '/v2/carts/' + cartId + '/recover',
    JSON.stringify({}),
    { headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf }, redirects: 0 }
  );
  if (res.status === 200) {
    const c = getCsrfFromResp(res);
    return c || csrf;
  }
  return csrf;
}

function authedPost(url, body, csrf, extraHeaders) {
  const headers = Object.assign(
    { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
    extraHeaders || {}
  );
  return http.post(url, JSON.stringify(body), { headers: headers, redirects: 0 });
}

function authedPatch(url, body, csrf, extraHeaders) {
  const headers = Object.assign(
    { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
    extraHeaders || {}
  );
  return http.patch(url, JSON.stringify(body), { headers: headers, redirects: 0 });
}

function collectProducts() {
  const products = [];
  // First page
  const r1 = http.get(BASE + '/v2/catalog', { redirects: 0 });
  check(r1, { 'catalog 200': (r) => r.status === 200 });
  const j1 = parseJson(r1.body);
  if (j1 && j1.data && Array.isArray(j1.data.products)) {
    for (const p of j1.data.products) products.push(p);
  }
  // Paginated traversal up to 3 pages
  let next = j1 && j1.next;
  let pages = 0;
  while (next && pages < 3) {
    const url = next.startsWith('http') ? next : BASE + next;
    const r = http.get(url, { redirects: 0 });
    if (r.status !== 200) break;
    const j = parseJson(r.body);
    if (!j) break;
    if (j.data && Array.isArray(j.data.products)) {
      for (const p of j.data.products) products.push(p);
    }
    next = j.next;
    pages++;
  }
  return products;
}

function pickVariant(product) {
  if (!product || !Array.isArray(product.variants)) return null;
  for (const v of product.variants) {
    if (v && v.in_stock) return v;
  }
  return product.variants[0] || null;
}

function solveChallenge(csrf) {
  const formRes = http.get(BASE + '/v2/challenge-form', { redirects: 0 });
  if (formRes.status !== 200) return null;
  const body = formRes.body;
  const actionMatch = body.match(/<form\b[^>]*\baction\s*=\s*("([^"]*)"|'([^']*)'|([^\s>]+))/i);
  if (!actionMatch) return null;
  const action = actionMatch[2] !== undefined ? actionMatch[2]
    : actionMatch[3] !== undefined ? actionMatch[3]
    : actionMatch[4];
  const challenge = parseCsrfFromForm(body.replace(/name\s*=\s*("|')?csrf\1?/gi, 'name=__csrf__'))
    || (function () {
      const tagRe = /<input\b[^>]*>/gi;
      let m;
      while ((m = tagRe.exec(body)) !== null) {
        const tag = m[0];
        const nameMatch = tag.match(/\bname\s*=\s*("([^"]*)"|'([^']*)'|([^\s>]+))/i);
        if (!nameMatch) continue;
        const nv = nameMatch[2] !== undefined ? nameMatch[2]
          : nameMatch[3] !== undefined ? nameMatch[3]
          : nameMatch[4];
        if (nv !== 'challenge') continue;
        const valMatch = tag.match(/\bvalue\s*=\s*("([^"]*)"|'([^']*)'|([^\s>]+))/i);
        if (!valMatch) continue;
        return valMatch[2] !== undefined ? valMatch[2]
          : valMatch[3] !== undefined ? valMatch[3]
          : valMatch[4];
      }
      return null;
    })();
  if (!action || !challenge) return null;

  const actionUrl = action.startsWith('http') ? action : BASE + action;
  const postRes = http.post(
    actionUrl,
    JSON.stringify({ challenge: challenge }),
    { headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf }, redirects: 0 }
  );
  if (postRes.status !== 302) return null;
  const loc = postRes.headers['Location'] || postRes.headers['location'];
  if (!loc) return null;
  const locUrl = loc.startsWith('http') ? loc : BASE + loc;
  const getRes = http.get(locUrl, { redirects: 0 });
  if (getRes.status !== 200) return null;
  const j = parseJson(getRes.body);
  if (!j) return null;
  return { grant_id: j.grant_id, csrf: j.csrf || csrf };
}

function pollReservation(statusUrl, csrf) {
  let currentCsrf = csrf;
  for (let i = 0; i < 5; i++) {
    if (i > 0) {
      // sleep at least 50ms
      const start = Date.now();
      while (Date.now() - start < 60) { /* busy wait */ }
    }
    const url = statusUrl.startsWith('http') ? statusUrl : BASE + statusUrl;
    const res = http.get(url, { headers: { 'X-CSRF-Token': currentCsrf }, redirects: 0 });
    if (res.status !== 200) return { status: 'error', csrf: currentCsrf };
    const j = parseJson(res.body);
    if (!j) return { status: 'error', csrf: currentCsrf };
    if (j.csrf) currentCsrf = j.csrf;
    if (j.status === 'ready') return { status: 'ready', reservation_id: j.reservation_id, csrf: currentCsrf };
    if (j.status === 'failed') return { status: 'failed', csrf: currentCsrf };
    // pending -> continue
  }
  return { status: 'timeout', csrf: currentCsrf };
}

export default function () {
  const vu = __VU;
  const iter = __ITER;
  const user = USERS[(vu - 1) % USERS.length];

  let csrf = loginFlow(user);
  if (!csrf) return;

  // Collect products
  const products = collectProducts();
  check(products.length > 0, { 'products available': (v) => v });
  if (products.length === 0) return;

  // Pick a product with a variant
  let chosen = null;
  let variant = null;
  for (const p of products) {
    const v = pickVariant(p);
    if (v) { chosen = p; variant = v; break; }
  }
  if (!chosen || !variant) return;

  // Challenge for grant
  let grant = solveChallenge(csrf);
  let grantId = grant ? grant.grant_id : null;
  if (grant && grant.csrf) csrf = grant.csrf;

  // Create cart
  const cartBody = { product_id: chosen.id, variant_id: variant.id };
  if (grantId) cartBody.grant_id = grantId;

  let cartRes = authedPost(BASE + '/v2/carts', cartBody, csrf);
  if (isExpired(cartRes)) {
    const newCsrf = renewSession(csrf);
    if (newCsrf) csrf = newCsrf;
    cartRes = authedPost(BASE + '/v2/carts', cartBody, csrf);
  } else if (isSessionRevoked(cartRes)) {
    const newCsrf = loginFlow(user);
    if (newCsrf) csrf = newCsrf;
    cartRes = authedPost(BASE + '/v2/carts', cartBody, csrf);
  }
  check(cartRes, { 'cart created 201': (r) => r.status === 201 });
  if (cartRes.status !== 201) return;

  const cartJson = parseJson(cartRes.body);
  if (!cartJson || !cartJson.id) return;
  const cartId = cartJson.id;
  if (cartJson.csrf) csrf = cartJson.csrf;
  let etag = cartRes.headers['Etag'] || cartRes.headers['ETag'] || cartRes.headers['etag'];

  // PATCH quantity
  const patchBody = { quantity: 1 };
  let patchRes = authedPatch(BASE + '/v2/carts/' + cartId, patchBody, csrf, etag ? { 'If-Match': etag } : {});
  if (patchRes.status === 412) {
    // re-read
    const readRes = http.get(BASE + '/v2/carts/' + cartId, { headers: { 'X-CSRF-Token': csrf }, redirects: 0 });
    if (readRes.status === 200) {
      etag = readRes.headers['Etag'] || readRes.headers['ETag'] || readRes.headers['etag'];
      const rj = parseJson(readRes.body);
      if (rj && rj.csrf) csrf = rj.csrf;
      patchRes = authedPatch(BASE + '/v2/carts/' + cartId, patchBody, csrf, etag ? { 'If-Match': etag } : {});
    }
  } else if (isExpired(patchRes)) {
    const newCsrf = renewSession(csrf);
    if (newCsrf) csrf = newCsrf;
    patchRes = authedPatch(BASE + '/v2/carts/' + cartId, patchBody, csrf, etag ? { 'If-Match': etag } : {});
  } else if (isSessionRevoked(patchRes)) {
    const newCsrf = loginFlow(user);
    if (newCsrf) csrf = newCsrf;
    csrf = recoverCart(cartId, csrf);
    patchRes = authedPatch(BASE + '/v2/carts/' + cartId, patchBody, csrf, etag ? { 'If-Match': etag } : {});
  }
  check(patchRes, { 'cart patched': (r) => r.status === 200 || r.status === 204 });
  if (patchRes.status === 200) {
    const pj = parseJson(patchRes.body);
    if (pj && pj.csrf) csrf = pj.csrf;
  }
  const newEtag = patchRes.headers['Etag'] || patchRes.headers['ETag'] || patchRes.headers['etag'];
  if (newEtag) etag = newEtag;

  // Reservation
  let resRes = authedPost(BASE + '/v2/reservations', { cart_id: cartId }, csrf);
  if (isExpired(resRes)) {
    const newCsrf = renewSession(csrf);
    if (newCsrf) csrf = newCsrf;
    resRes = authedPost(BASE + '/v2/reservations', { cart_id: cartId }, csrf);
  } else if (isSessionRevoked(resRes)) {
    const newCsrf = loginFlow(user);
    if (newCsrf) csrf = newCsrf;
    csrf = recoverCart(cartId, csrf);
    resRes = authedPost(BASE + '/v2/reservations', { cart_id: cartId }, csrf);
  }
  check(resRes, { 'reservation 202': (r) => r.status === 202 });
  if (resRes.status !== 202) return;

  const resJson = parseJson(resRes.body);
  if (!resJson || !resJson.status_url) return;
  if (resJson.csrf) csrf = resJson.csrf;

  const poll = pollReservation(resJson.status_url, csrf);
  csrf = poll.csrf;
  check(poll.status, { 'reservation ready': (s) => s === 'ready' });
  if (poll.status !== 'ready') return;

  // Order
  const idemKey = 'idem-' + cartId + '-' + vu + '-' + iter;
  const orderBody = { cart_id: cartId, reservation_id: poll.reservation_id };
  const orderHeaders = { 'Idempotency-Key': idemKey };
  if (etag) orderHeaders['If-Match'] = etag;

  let orderRes = authedPost(BASE + '/v2/orders', orderBody, csrf, orderHeaders);
  if (isExpired(orderRes)) {
    const newCsrf = renewSession(csrf);
    if (newCsrf) csrf = newCsrf;
    orderRes = authedPost(BASE + '/v2/orders', orderBody, csrf, orderHeaders);
  } else if (isSessionRevoked(orderRes)) {
    const newCsrf = loginFlow(user);
    if (newCsrf) csrf = newCsrf;
    csrf = recoverCart(cartId, csrf);
    orderRes = authedPost(BASE + '/v2/orders', orderBody, csrf, orderHeaders);
  }

  check(orderRes, {
    'order 201': (r) => r.status === 201,
    'order accepted': (r) => {
      const j = parseJson(r.body);
      return j && j.accepted === true;
    },
  });
}
