import http from 'k6/http';
import { check } from 'k6';

const BASE = __ENV.BASE_URL || 'http://127.0.0.1:8000';

export const options = {
  scenarios: {
    flow: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '5m',
    },
  },
  thresholds: {
    checks: ['rate==1'],
  },
};

function parseCsrf(html) {
  // Find all input tags, then pick the one whose name attribute is csrf,
  // regardless of attribute ordering or decoys.
  const inputs = html.match(/<input\b[^>]*>/gi) || [];
  for (const tag of inputs) {
    const nameMatch = tag.match(/\bname\s*=\s*("([^"]*)"|'([^']*)'|([^\s>]+))/i);
    if (!nameMatch) continue;
    const name = nameMatch[2] !== undefined ? nameMatch[2]
      : nameMatch[3] !== undefined ? nameMatch[3]
      : nameMatch[4];
    if (name !== 'csrf') continue;
    const valMatch = tag.match(/\bvalue\s*=\s*("([^"]*)"|'([^']*)'|([^\s>]+))/i);
    if (!valMatch) continue;
    const val = valMatch[2] !== undefined ? valMatch[2]
      : valMatch[3] !== undefined ? valMatch[3]
      : valMatch[4];
    return val;
  }
  return null;
}

function parseJson(res) {
  try { return res.json(); } catch (e) { return null; }
}

function getLocation(res) {
  return res.headers['Location'] || res.headers['location'] || null;
}

function loginFlow(user) {
  // Fresh login
  const formRes = http.get(`${BASE}/v2/login-form`, { redirects: 0 });
  check(formRes, { 'login-form 200': (r) => r.status === 200 });
  const csrf = parseCsrf(formRes.body);
  check(csrf, { 'csrf extracted': (c) => !!c });
  if (!csrf) return null;

  const loginRes = http.post(`${BASE}/v2/login`, JSON.stringify({
    username: user, password: 'bench', csrf: csrf,
  }), {
    headers: { 'Content-Type': 'application/json' },
    redirects: 0,
  });

  let token = csrf;
  let sessionOk = false;
  if (loginRes.status === 200) {
    const body = parseJson(loginRes);
    if (body && body.csrf) token = body.csrf;
    sessionOk = true;
  } else if (loginRes.status === 302) {
    const loc = getLocation(loginRes);
    if (loc) {
      const followRes = http.get(loc.startsWith('http') ? loc : `${BASE}${loc}`, { redirects: 0 });
      const body = parseJson(followRes);
      if (body && body.csrf) token = body.csrf;
      sessionOk = followRes.status === 200;
    }
  }
  check(sessionOk, { 'login authorized': (v) => v === true });
  return sessionOk ? token : null;
}

function authHeaders(token, extra) {
  const h = { 'X-CSRF-Token': token, 'Content-Type': 'application/json' };
  if (extra) Object.assign(h, extra);
  return h;
}

function handleExpiry(res, token, cartId, retryFn) {
  if (res.status !== 401) return { handled: false };
  const body = parseJson(res);
  const err = body && body.error;
  if (err === 'expired') {
    const renewRes = http.post(`${BASE}/v2/session/renew`, '{}', {
      headers: authHeaders(token),
    });
    let newToken = token;
    if (renewRes.status === 200) {
      const rb = parseJson(renewRes);
      if (rb && rb.csrf) newToken = rb.csrf;
    }
    if (cartId) {
      http.post(`${BASE}/v2/carts/${cartId}/recover`, '{}', {
        headers: authHeaders(newToken),
      });
    }
    return { handled: true, token: newToken, retry: retryFn(newToken) };
  }
  if (err === 'session') {
    return { handled: true, revoked: true };
  }
  return { handled: false };
}

function collectProducts() {
  const products = [];
  // First page
  const r1 = http.get(`${BASE}/v2/catalog`);
  const b1 = parseJson(r1);
  if (b1 && b1.data && b1.data.products) {
    for (const p of b1.data.products) products.push(p);
  }
  let next = b1 && b1.next;
  let pages = 1;
  while (next && pages < 3) {
    const url = next.startsWith('http') ? next : `${BASE}${next}`;
    const r = http.get(url);
    const b = parseJson(r);
    if (!b) break;
    if (b.data && b.data.products) {
      for (const p of b.data.products) products.push(p);
    }
    next = b.next;
    pages++;
  }
  return products;
}

function pickVariant(products) {
  for (const p of products) {
    if (!p.variants) continue;
    for (const v of p.variants) {
      if (v.in_stock) return { product_id: p.id, variant_id: v.id };
    }
  }
  return null;
}

function solveChallenge(token) {
  const formRes = http.get(`${BASE}/v2/challenge-form`, { redirects: 0 });
  if (formRes.status !== 200) return null;
  const html = formRes.body;
  const actionMatch = html.match(/<form\b[^>]*\baction\s*=\s*("([^"]*)"|'([^']*)'|([^\s>]+))/i);
  if (!actionMatch) return null;
  const action = actionMatch[2] !== undefined ? actionMatch[2]
    : actionMatch[3] !== undefined ? actionMatch[3]
    : actionMatch[4];
  const inputs = html.match(/<input\b[^>]*>/gi) || [];
  let challenge = null;
  for (const tag of inputs) {
    const nm = tag.match(/\bname\s*=\s*("([^"]*)"|'([^']*)'|([^\s>]+))/i);
    if (!nm) continue;
    const name = nm[2] !== undefined ? nm[2] : nm[3] !== undefined ? nm[3] : nm[4];
    if (name !== 'challenge') continue;
    const vm = tag.match(/\bvalue\s*=\s*("([^"]*)"|'([^']*)'|([^\s>]+))/i);
    if (!vm) continue;
    challenge = vm[2] !== undefined ? vm[2] : vm[3] !== undefined ? vm[3] : vm[4];
  }
  if (!challenge) return null;
  const actionUrl = action.startsWith('http') ? action : `${BASE}${action}`;
  const postRes = http.post(actionUrl, JSON.stringify({ challenge }), {
    headers: authHeaders(token),
    redirects: 0,
  });
  if (postRes.status !== 302) return null;
  const loc = getLocation(postRes);
  if (!loc) return null;
  const followRes = http.get(loc.startsWith('http') ? loc : `${BASE}${loc}`, { redirects: 0 });
  const body = parseJson(followRes);
  if (!body) return null;
  return { grant_id: body.grant_id, csrf: body.csrf || token };
}

function createCart(token, product_id, variant_id, grant_id) {
  const payload = { product_id, variant_id };
  if (grant_id) payload.grant_id = grant_id;
  const res = http.post(`${BASE}/v2/carts`, JSON.stringify(payload), {
    headers: authHeaders(token),
  });
  if (res.status === 201) {
    const body = parseJson(res);
    return { cart: body, etag: res.headers['Etag'] || res.headers['etag'], token: (body && body.csrf) || token };
  }
  return null;
}

function patchQuantity(token, cartId, etag, qty) {
  const doPatch = (tok, et) => http.patch(`${BASE}/v2/carts/${cartId}`, JSON.stringify({ quantity: qty }), {
    headers: authHeaders(tok, et ? { 'If-Match': et } : {}),
  });
  let res = doPatch(token, etag);
  if (res.status === 412) {
    const re = http.get(`${BASE}/v2/carts/${cartId}`);
    const newEtag = re.headers['Etag'] || re.headers['etag'];
    res = doPatch(token, newEtag);
  }
  return res;
}

function reserve(token, cartId) {
  const res = http.post(`${BASE}/v2/reservations`, JSON.stringify({ cart_id: cartId }), {
    headers: authHeaders(token),
  });
  if (res.status !== 202) return null;
  const body = parseJson(res);
  if (!body || !body.status_url) return null;
  let tok = body.csrf || token;
  const statusUrl = body.status_url.startsWith('http') ? body.status_url : `${BASE}${body.status_url}`;
  for (let i = 0; i < 5; i++) {
    const poll = http.get(statusUrl);
    const pb = parseJson(poll);
    if (pb && pb.status === 'ready' && pb.reservation_id) {
      return { reservation_id: pb.reservation_id, token: pb.csrf || tok };
    }
    if (pb && (pb.status === 'failed')) return null;
    // sleep 50ms
    const start = Date.now();
    while (Date.now() - start < 50) { /* busy wait minimal */ }
  }
  return null;
}

function placeOrder(token, cartId, reservationId, etag) {
  const idem = `idem-${cartId}-${__VU}-${__ITER}`;
  const doPost = (tok, et) => http.post(`${BASE}/v2/orders`, JSON.stringify({
    cart_id: cartId, reservation_id: reservationId,
  }), {
    headers: authHeaders(tok, Object.assign({ 'Idempotency-Key': idem }, et ? { 'If-Match': et } : {})),
  });
  let res = doPost(token, etag);
  if (res.status === 412) {
    const re = http.get(`${BASE}/v2/carts/${cartId}`);
    const newEtag = re.headers['Etag'] || re.headers['etag'];
    res = doPost(token, newEtag);
  }
  return res;
}

export default function () {
  const user = `bench-${((__VU - 1) % 16) + 1}`;
  let token = loginFlow(user);
  if (!token) return;

  const products = collectProducts();
  const pick = pickVariant(products);
  check(pick, { 'variant picked': (v) => !!v });
  if (!pick) return;

  // Challenge for grant
  const chal = solveChallenge(token);
  let grant_id = chal ? chal.grant_id : null;
  if (chal && chal.csrf) token = chal.csrf;

