  check(cartRes, { 'cart created': (c) => !!c });
  if (!cartRes) return;
  let cartId = cartRes.cart.id;
  let etag = cartRes.etag;
  token = cartRes.token;

  // Patch quantity
  const patchRes = patchQuantity(token, cartId, etag, 1);
  check(patchRes, { 'cart patched': (r) => r.status === 200 || r.status === 204 });
  if (patchRes.status === 200) {
    const pb = parseJson(patchRes);
    if (pb && pb.csrf) token = pb.csrf;
  }
  const reRead = http.get(`${BASE}/v2/carts/${cartId}`);
  etag = reRead.headers['Etag'] || reRead.headers['etag'] || etag;

  // Reservation
  const resv = reserve(token, cartId);
  check(resv, { 'reservation ready': (r) => !!r });
  if (!resv) return;
  token = resv.token;

  // Order
  const orderRes = placeOrder(token, cartId, resv.reservation_id, etag);
  const ob = parseJson(orderRes);
  check(orderRes, {
    'order 201': (r) => r.status === 201,
    'order accepted': () => ob && ob.accepted === true,
  });
}
