  const m = body.match(re);
  if (!m) return null;
  const tag = m[0];
  const vm = tag.match(/value\s*=\s*["']([^"']*)["']/i);
  return vm ? vm[1] : null;
}

function getLocation(res) {
  return res.headers['Location'] || res.headers['location'];
}

function login(jarRef) {
  const formRes = http.get(`${BASE}/v2/login-form`, { jar: jarRef, redirects: 0 });
  check(formRes, { 'login-form 200': (r) => r.status === 200 });
  const csrf = parseCsrfFromForm(formRes.body);
  check(csrf, { 'csrf found': (c) => !!c });
