    JSON.stringify({ username: user, password: 'bench', csrf }),
    { jar: jarRef, redirects: 0, headers: { 'Content-Type': 'application/json' } }
  );
  let token = csrf;
  if (loginRes.status === 302) {
    const loc = getLocation(loginRes);
    if (loc) {
      const follow = http.get(loc.startsWith('http') ? loc : `${BASE}${loc}`, { jar: jarRef, redirects: 0 });
      check(follow, { 'login redirect ok': (r) => r.status >= 200 && r.status < 400 });
    }
  } else {
    check(loginRes, { 'login 200/302': (r) => r.status === 200 || r.status === 302 });
    try {
      const b = JSON.parse(loginRes.body);
      if (b && b.csrf) token = b.csrf;
    } catch (e) {}
  }
  return token;
}

function fetchCatalog(jarRef) {
  const res = http.get(`${BASE}/v2/catalog`, { jar: jarRef, redirects: 0 });
  check(res, { 'catalog 200': (r) => r.status === 200 });
  try {
    const b = JSON.parse(res.body);
    return (b && b.data && b.data.products) || [];
  } catch (e) {
    return [];
  }
}

function fetchCatalogPage(jarRef, url) {
  const res = http.get(url.startsWith('http') ? url : `${BASE}${url}`, { jar: jarRef, redirects: 0 });
  check(res, { 'catalog page 200': (r) => r.status === 200 });
  try {
    return JSON.parse(res.body);
  } catch (e) {
    return null;
  }
}

function selectParentAndVariant(jarRef) {
  // Try catalog first
  let products = fetchCatalog(jarRef);
  let chosen = null;
  for (const p of products) {
    if (!p || !p.variants) continue;
    const v = p.variants.find((x) => x && x.in_stock);
    if (v) {
      chosen = { product_id: p.id, variant_id: v.id };
      break;
    }
  }
  if (chosen) return chosen;

  // Traverse catalog pages up to 3
  let next = '/v2/catalog/page';
  let pages = 0;
  while (next && pages < 3) {
    const page = fetchCatalogPage(jarRef, next);
    pages++;
    if (!page) break;
    const p = page.product || (page.data && page.data.product);
    if (p && p.variants) {
      const v = p.variants.find((x) => x && x.in_stock);
      if (v) return { product_id: p.id, variant_id: v.id };
    }
    next = page.next;
  }
  return null;
}

function solveChallenge(jarRef, csrf) {
  const formRes = http.get(`${BASE}/v2/challenge-form`, { jar: jarRef, redirects: 0 });
  check(formRes, { 'challenge-form 200': (r) => r.status === 200 });
  const actionM = formRes.body.match(/action\s*=\s*["']([^"']+)["']/i);
  const challengeM = formRes.body.match(/<input[^>]*name\s*=\s*["']?challenge["']?[^>]*>/i);
  if (!actionM || !challengeM) return null;
  const action = actionM[1];
  const vm = challengeM[0].match(/value\s*=\s*["']([^"']*)["']/i);
  const challenge = vm ? vm[1] : '';
  const postRes = http.post(
    action.startsWith('http') ? action : `${BASE}${action}`,
    JSON.stringify({ challenge }),
    { jar: jarRef, redirects: 0, headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf } }
