  if (!loc) return null;
  const follow = http.get(loc.startsWith('http') ? loc : `${BASE}${loc}`, { jar: jarRef, redirects: 0 });
  check(follow, { 'challenge follow 200': (r) => r.status === 200 });
  try {
    const b = JSON.parse(follow.body);
    return { grant_id: b.grant_id, csrf: b.csrf || csrf };
  } catch (e) {
    return null;
  }
}

