  const payload = { product_id, variant_id };
  if (grant_id) payload.grant_id = grant_id;
  const res = http.post(`${BASE}/v2/carts`, JSON.stringify(payload), {
    jar: jarRef,
    redirects: 0,
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
  });
  check(res, { 'cart 201': (r) => r.status === 201 });
  let body = {};
  try { body = JSON.parse(res.body); } catch (e) {}
  return { id: body.id, csrf: body.csrf || csrf, etag: res.headers['Etag'] || res.headers['etag'] };
}

function getCart(jarRef, cartId) {
  const res = http.get(`${BASE}/v2/carts/${cartId}`, { jar: jarRef, redirects: 0 });
  check(res, { 'cart get 200': (r) => r.status === 200 });
  return res.headers['Etag'] || res.headers['etag'];
}

function patchCart(jarRef, csrf, cartId, etag, quantity) {
  const payload = JSON.stringify({ quantity });
  let res = http.patch(`${BASE}/v2/carts/${cartId}`, payload, {
    jar: jarRef,
    redirects: 0,
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf, 'If-Match': etag || '' },
  });
  if (res.status === 412) {
    const newEtag = getCart(jarRef, cartId);
    res = http.patch(`${BASE}/v2/carts/${cartId}`, payload, {
      jar: jarRef,
      redirects: 0,
      headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf, 'If-Match': newEtag || '' },
    });
  }
  check(res, { 'cart patch ok': (r) => r.status === 200 || r.status === 204 });
  let body = {};
  try { body = JSON.parse(res.body); } catch (e) {}
  return { csrf: body.csrf || csrf, etag: res.headers['Etag'] || res.headers['etag'] };
}

function reserve(jarRef, csrf, cartId) {
  const res = http.post(`${BASE}/v2/reservations`, JSON.stringify({ cart_id: cartId }), {
    jar: jarRef,
    redirects: 0,
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
  });
  check(res, { 'reservation 202': (r) => r.status === 202 });
  let body = {};
  try { body = JSON.parse(res.body); } catch (e) {}
  const statusUrl = body.status_url;
  let token = body.csrf || csrf;
  if (!statusUrl) return { reservation_id: null, csrf: token };
  for (let i = 0; i < 5; i++) {
    if (i > 0) {
      // sleep at least 50ms
      const start = Date.now();
      while (Date.now() - start < 60) {}
    }
    const sres = http.get(statusUrl.startsWith('http') ? statusUrl : `${BASE}${statusUrl}`, {
      jar: jarRef,
      redirects: 0,
    });
    check(sres, { 'status poll 200': (r) => r.status === 200 });
    let sb = {};
    try { sb = JSON.parse(sres.body); } catch (e) {}
    if (sb.csrf) token = sb.csrf;
    if (sb.status === 'ready') {
      return { reservation_id: sb.reservation_id, csrf: token };
    }
    if (sb.status === 'failed') {
      return { reservation_id: null, csrf: token };
    }
  }
  return { reservation_id: null, csrf: token };
}

function placeOrder(jarRef, csrf, cartId, reservation_id, etag) {
  const payload = { cart_id: cartId };
  if (reservation_id) payload.reservation_id = reservation_id;
  const headers = {
    'Content-Type': 'application/json',
    'X-CSRF-Token': csrf,
    'Idempotency-Key': `idem-${cartId}-${__VU}-${__ITER}`,
  };
  if (etag) headers['If-Match'] = etag;
  const res = http.post(`${BASE}/v2/orders`, JSON.stringify(payload), {
    jar: jarRef,
    redirects: 0,
    headers,
  });
  check(res, { 'order 201': (r) => r.status === 201 });
  let body = {};
  try { body = JSON.parse(res.body); } catch (e) {}
  check(body, { 'order accepted': (b) => b && b.accepted === true });
  return body;
}

export default function () {
  const jarRef = jar();
  let csrf = login(jarRef);

  const sel = selectParentAndVariant(jarRef);
  check(sel, { 'selected in-stock variant': (s) => !!s });
  if (!sel) return;

  // Attempt challenge for grant_id (optional but protocol-supported)
  let grant = null;
  try {
    grant = solveChallenge(jarRef, csrf);
    if (grant && grant.csrf) csrf = grant.csrf;
  } catch (e) {}

  const cart = createCart(jarRef, csrf, sel.product_id, sel.variant_id, grant ? grant.grant_id : null);
  check(cart, { 'cart created': (c) => !!c.id });
  if (!cart.id) return;
  csrf = cart.csrf;

  const patched = patchCart(jarRef, csrf, cart.id, cart.etag, 1);
  csrf = patched.csrf;

  const resv = reserve(jarRef, csrf, cart.id);
  csrf = resv.csrf;

  const order = placeOrder(jarRef, csrf, cart.id, resv.reservation_id, patched.etag);
  check(order, { 'order id present': (o) => !!o.id });
}
