  thresholds: {
    checks: ['rate==1'],
  },
};

function jar() {
  return new http.CookieJar();
}

function getCsrfFromHtml(body) {
  // input[name=csrf] with possible attribute variants / decoys
  const re = /<input\b[^>]*\bname\s*=\s*["']?csrf["']?[^>]*>/i;
  const m = body.match(re);
  if (!m) return null;
  const tag = m[0];
  const vm = tag.match(/\bvalue\s*=\s*["']([^"']*)["']/i);
  return vm ? vm[1] : null;
}

function parseJson(res) {
  try { return JSON.parse(res.body); } catch (e) { return null; }
}

function login(jarRef) {
  const formRes = http.get(`${BASE}/v2/login-form`, { jar: jarRef, redirects: 0 });
  check(formRes, { 'login-form 200': (r) => r.status === 200 });
  const csrf = getCsrfFromHtml(formRes.body);
  check(csrf, { 'csrf extracted': (c) => !!c });

  const user = `bench-${1 + (__VU % 16)}`;
  const loginRes = http.post(`${BASE}/v2/login`,
    JSON.stringify({ username: user, password: 'bench', csrf }),
    { jar: jarRef, redirects: 0, headers: { 'Content-Type': 'application/json' } });

  if (loginRes.status === 302) {
    const loc = loginRes.headers['Location'] || loginRes.headers['location'];
    if (loc) {
      const follow = http.get(loc.startsWith('http') ? loc : `${BASE}${loc}`, { jar: jarRef, redirects: 0 });
      check(follow, { 'login redirect followed': (r) => r.status < 400 });
    }
  } else {
    check(loginRes, { 'login 200/302': (r) => r.status === 200 || r.status === 302 });
  }

  const body = parseJson(loginRes);
  let token = body && body.csrf ? body.csrf : csrf;
  return { csrf: token, user };
}

function renewSession(jarRef, csrf) {
  const r = http.post(`${BASE}/v2/session/renew`, '{}', {
    jar: jarRef, redirects: 0,
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
  });
  const b = parseJson(r);
  return { ok: r.status === 200, csrf: (b && b.csrf) || csrf };
}

function recoverCart(jarRef, csrf, cartId) {
  const r = http.post(`${BASE}/v2/carts/${cartId}/recover`, '{}', {
    jar: jarRef, redirects: 0,
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
  });
  const b = parseJson(r);
  return { ok: r.status === 200, csrf: (b && b.csrf) || csrf };
}

function findEligibleProduct(jarRef) {
  // First try catalog root
  const root = http.get(`${BASE}/v2/catalog`, { jar: jarRef, redirects: 0 });
  check(root, { 'catalog 200': (r) => r.status === 200 });
  const rootBody = parseJson(root);
  if (rootBody && rootBody.data && Array.isArray(rootBody.data.products)) {
    for (const p of rootBody.data.products) {
      if (!p || !Array.isArray(p.variants)) continue;
      for (const v of p.variants) {
        if (v && v.in_stock) return { product_id: p.id, variant_id: v.id };
      }
    }
  }

  // Paginate via /v2/catalog/page, at most 3 pages
  let next = '/v2/catalog/page';
  let pages = 0;
  while (next && pages < 3) {
    pages++;
    const url = next.startsWith('http') ? next : `${BASE}${next}`;
    const r = http.get(url, { jar: jarRef, redirects: 0 });
    check(r, { 'catalog page 200': (res) => res.status === 200 });
    const b = parseJson(r);
    if (!b) break;
    const prod = b.data && b.data.product ? b.data.product : (b.product || null);
    if (prod && Array.isArray(prod.variants)) {
      for (const v of prod.variants) {
        if (v && v.in_stock) return { product_id: prod.id, variant_id: v.id };
      }
    }
    next = b.next || null;
  }
  return null;
}

function maybeChallenge(jarRef, csrf) {
  // Attempt challenge flow; if not present, return null
  const r = http.get(`${BASE}/v2/challenge-form`, { jar: jarRef, redirects: 0 });
  if (r.status !== 200) return { csrf, grant_id: null };
  const actionMatch = r.body.match(/action\s*=\s*["']([^"']*\/v2\/challenges\/[^"']+)["']/i);
  const inputMatch = r.body.match(/<input\b[^>]*\bname\s*=\s*["']?challenge["']?[^>]*>/i);
  if (!actionMatch || !inputMatch) return { csrf, grant_id: null };
  const action = actionMatch[1];
  const vm = inputMatch[0].match(/\bvalue\s*=\s*["']([^"']*)["']/i);
  const challenge = vm ? vm[1] : '';
  const post = http.post(action.startsWith('http') ? action : `${BASE}${action}`,
    JSON.stringify({ challenge }),
    { jar: jarRef, redirects: 0, headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf } });
  let newCsrf = csrf;
  if (post.status === 302) {
    const loc = post.headers['Location'] || post.headers['location'];
    if (loc) {
      const follow = http.get(loc.startsWith('http') ? loc : `${BASE}${loc}`, { jar: jarRef, redirects: 0 });
      const b = parseJson(follow);
      if (b && b.csrf) newCsrf = b.csrf;
      if (b && b.grant_id) return { csrf: newCsrf, grant_id: b.grant_id };
    }
  }
  return { csrf: newCsrf, grant_id: null };
}

function createCart(jarRef, csrf, product_id, variant_id, grant_id) {
  const payload = { product_id, variant_id };
  if (grant_id) payload.grant_id = grant_id;
  const r = http.post(`${BASE}/v2/carts`, JSON.stringify(payload), {
    jar: jarRef, redirects: 0,
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
  });
  const b = parseJson(r);
  return {
    status: r.status,
    id: b && b.id,
    csrf: (b && b.csrf) || csrf,
    etag: r.headers['Etag'] || r.headers['ETag'] || r.headers['etag'],
  };
}

function patchQuantity(jarRef, csrf, cartId, etag, qty) {
  const doPatch = (et) => http.patch(`${BASE}/v2/carts/${cartId}`,
    JSON.stringify({ quantity: qty }),
    { jar: jarRef, redirects: 0,
      headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf, 'If-Match': et || '' } });

  let r = doPatch(etag);
  if (r.status === 412) {
    const re = http.get(`${BASE}/v2/carts/${cartId}`, { jar: jarRef, redirects: 0 });
    const newEtag = re.headers['Etag'] || re.headers['ETag'] || re.headers['etag'];
    r = doPatch(newEtag);
  }
  const b = parseJson(r);
  return { status: r.status, csrf: (b && b.csrf) || csrf };
}

function reserve(jarRef, csrf, cartId) {
  const r = http.post(`${BASE}/v2/reservations`, JSON.stringify({ cart_id: cartId }), {
    jar: jarRef, redirects: 0,
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
  });
  const b = parseJson(r);
  return { status: r.status, status_url: b && b.status_url, csrf: (b && b.csrf) || csrf };
}

function pollReservation(jarRef, csrf, statusUrl) {
  let reservation_id = null;
  for (let i = 0; i < 5; i++) {
    if (i > 0) {
      // sleep at least 50ms
      const start = Date.now();
      while (Date.now() - start < 60) { /* busy wait */ }
    }
    const url = statusUrl.startsWith('http') ? statusUrl : `${BASE}${statusUrl}`;
    const r = http.get(url, { jar: jarRef, redirects: 0 });
    const b = parseJson(r);
    if (!b) continue;
    if (b.status === 'ready' && b.reservation_id) {
      reservation_id = b.reservation_id;
      break;
    }
    if (b.status === 'failed') break;
  }
  return reservation_id;
}

function placeOrder(jarRef, csrf, cartId, reservation_id, idemKey, etag) {
  const payload = { cart_id: cartId };
  if (reservation_id) payload.reservation_id = reservation_id;
  const headers = {
    'Content-Type': 'application/json',
    'X-CSRF-Token': csrf,
    'Idempotency-Key': idemKey,
  };
  if (etag) headers['If-Match'] = etag;
  const r = http.post(`${BASE}/v2/orders`, JSON.stringify(payload), {
    jar: jarRef, redirects: 0, headers,
  });
  const b = parseJson(r);
  return {
    status: r.status,
    accepted: b && b.accepted === true,
    id: b && b.id,
    csrf: (b && b.csrf) || csrf,
  };
}

export default function () {
  const jarRef = jar();
  let { csrf } = login(jarRef);

  const product = findEligibleProduct(jarRef);
  check(product, { 'eligible product found': (p) => !!p });
  if (!product) return;

  const ch = maybeChallenge(jarRef, csrf);
  csrf = ch.csrf;

  let cart = createCart(jarRef, csrf, product.product_id, product.variant_id, ch.grant_id);
  if (cart.status === 401) {
    const ren = renewSession(jarRef, csrf);
    csrf = ren.csrf;
    cart = createCart(jarRef, csrf, product.product_id, product.variant_id, ch.grant_id);
  }
  check(cart, { 'cart created': (c) => c.status === 201 && !!c.id });
  if (cart.status !== 201 || !cart.id) return;
  csrf = cart.csrf;

  const patched = patchQuantity(jarRef, csrf, cart.id, cart.etag, 1);
  csrf = patched.csrf;
  check(patched, { 'cart patched': (p) => p.status === 200 || p.status === 204 });

  const res = reserve(jarRef, csrf, cart.id);
  csrf = res.csrf;
  check(res, { 'reservation accepted': (r) => r.status === 202 && !!r.status_url });
  if (res.status !== 202 || !res.status_url) return;

  const reservation_id = pollReservation(jarRef, csrf, res.status_url);
  check(reservation_id, { 'reservation ready': (rid) => !!rid });
  if (!reservation_id) return;

  const idemKey = `idem-${cart.id}-${__VU}-${__ITER}`;
  let order = placeOrder(jarRef, csrf, cart.id, reservation_id, idemKey, cart.etag);
  if (order.status === 401) {
    const ren = renewSession(jarRef, csrf);
    csrf = ren.csrf;
    const rec = recoverCart(jarRef, csrf, cart.id);
    csrf = rec.csrf;
    order = placeOrder(jarRef, csrf, cart.id, reservation_id, idemKey, cart.etag);
  }
  check(order, { 'order accepted': (o) => o.status === 201 && o.accepted && !!o.id });
}
