  },
};

function parseCsrf(html) {
  // input[name=csrf] with possible attribute variants / decoys
  const re = /<input\b[^>]*\bname\s*=\s*["']?csrf["']?[^>]*>/i;
  const m = html.match(re);
  if (!m) return null;
  const tag = m[0];
  const vm = tag.match(/\bvalue\s*=\s*["']([^"']*)["']/i);
  return vm ? vm[1] : null;
}

function getHeader(res, name) {
  const h = res.headers[name] || res.headers[name.toLowerCase()];
  return h || null;
}

function login(vu) {
  const jar = http.cookieJar();
  // fresh login: clear cookies for base
  jar.clear(BASE);

  const formRes = http.get(`${BASE}/v2/login-form`, { redirects: 0 });
  check(formRes, { 'login-form 200': (r) => r.status === 200 });
  const csrf = parseCsrf(formRes.body);
  check(csrf, { 'csrf extracted': (c) => !!c });

  const username = `bench-${((vu - 1) % 16) + 1}`;
  const loginRes = http.post(
    `${BASE}/v2/login`,
    JSON.stringify({ username, password: 'bench', csrf }),
    { headers: { 'Content-Type': 'application/json' }, redirects: 0 }
  );

  let token = null;
  if (loginRes.status === 302) {
    const loc = getHeader(loginRes, 'Location');
    if (loc) {
      const follow = http.get(loc.startsWith('http') ? loc : `${BASE}${loc}`, { redirects: 0 });
      try {
        const b = JSON.parse(follow.body);
        token = b.csrf;
      } catch (e) {}
    }
  } else if (loginRes.status === 200) {
    try {
      const b = JSON.parse(loginRes.body);
      token = b.csrf;
    } catch (e) {}
  }
  check(token, { 'login csrf': (t) => !!t });
  return token;
}

function pickProduct() {
  const res = http.get(`${BASE}/v2/catalog`, { redirects: 0 });
  check(res, { 'catalog 200': (r) => r.status === 200 });
  let body;
  try { body = JSON.parse(res.body); } catch (e) { return null; }
  const products = (body.data && body.data.products) || [];
  for (const p of products) {
    const variants = p.variants || [];
    for (const v of variants) {
      if (v.in_stock) return { product_id: p.id, variant_id: v.id };
    }
  }
  // fallback: paginate
  let next = body.next;
  let pages = 0;
  while (next && pages < 3) {
    pages++;
    const url = next.startsWith('http') ? next : `${BASE}${next}`;
    const r = http.get(url, { redirects: 0 });
    if (r.status !== 200) break;
    let b;
    try { b = JSON.parse(r.body); } catch (e) { break; }
    const prods = (b.data && b.data.products) || (b.product ? [b.product] : []);
    for (const p of prods) {
      for (const v of (p.variants || [])) {
        if (v.in_stock) return { product_id: p.id, variant_id: v.id };
      }
    }
    next = b.next;
  }
  return null;
}

function createCart(token, prod) {
  const res = http.post(
    `${BASE}/v2/carts`,
    JSON.stringify({ product_id: prod.product_id, variant_id: prod.variant_id }),
    {
      headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': token },
      redirects: 0,
    }
  );
  check(res, { 'cart 201': (r) => r.status === 201 });
  let body = {};
  try { body = JSON.parse(res.body); } catch (e) {}
  const etag = getHeader(res, 'ETag');
  return { id: body.id, csrf: body.csrf || token, etag };
}

function patchCart(token, cartId, etag, quantity) {
  const payload = JSON.stringify({ quantity });
  const headers = {
    'Content-Type': 'application/json',
    'X-CSRF-Token': token,
    'If-Match': etag,
  };
  let res = http.patch(`${BASE}/v2/carts/${cartId}`, payload, { headers, redirects: 0 });

  if (res.status === 412) {
    // re-read
    const re = http.get(`${BASE}/v2/carts/${cartId}`, { redirects: 0 });
    check(re, { 'reread 200': (r) => r.status === 200 });
    const newEtag = getHeader(re, 'ETag');
    check(newEtag, { 'reread etag': (e) => !!e });
    const headers2 = {
      'Content-Type': 'application/json',
      'X-CSRF-Token': token,
      'If-Match': newEtag,
    };
    res = http.patch(`${BASE}/v2/carts/${cartId}`, payload, { headers: headers2, redirects: 0 });
  }

  check(res, { 'patch 200': (r) => r.status === 200 });
  let body = {};
  try { body = JSON.parse(res.body); } catch (e) {}
  return { res, csrf: body.csrf || token };
}

export default function () {
  const vu = __VU;
  let token = login(vu);
  if (!token) return;

  const prod = pickProduct();
  if (!prod) return;

  const cart = createCart(token, prod);
  if (!cart.id || !cart.etag) return;
  token = cart.csrf;

  const patched = patchCart(token, cart.id, cart.etag, 2);
  token = patched.csrf;

  // one committed order per journey
  const orderRes = http.post(
    `${BASE}/v2/orders`,
    JSON.stringify({ cart_id: cart.id }),
    {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': token,
        'Idempotency-Key': `order-${cart.id}`,
      },
      redirects: 0,
    }
  );
  check(orderRes, {
    'order 201': (r) => r.status === 201,
    'order accepted': (r) => {
      try { return JSON.parse(r.body).accepted === true; } catch (e) { return false; }
    },
  });
}
