# CSRF Rotation Flow — k6 1.0.0

```javascript
import http from 'k6/http';
import { check } from 'k6';

const BASE = __ENV.BASE_URL || 'http://127.0.0.1:8000';

export const options = {
  scenarios: {
    flow: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '5m',
    },
  },
  thresholds: {
    checks: ['rate==1'],
  },
};

// ---- helpers -------------------------------------------------------------

function jar() {
  // fresh cookie jar per journey
  return http.cookieJar();
}

function extractCsrf(html) {
  if (!html) return null;
  // input[name=csrf] with mixed attribute order / quoting / decoys
  const re = /<input\b[^>]*\bname\s*=\s*["']?csrf["']?[^>]*>/gi;
  let m;
  while ((m = re.exec(html)) !== null) {
    const tag = m[0];
    const v = /\bvalue\s*=\s*("([^"]*)"|'([^']*)'|([^\s>]+))/i.exec(tag);
    if (v) {
      const val = v[2] !== undefined ? v[2] : v[3] !== undefined ? v[3] : v[4];
      if (val) return val;
    }
  }
  return null;
}

function extractLoginNonce(res) {
  // cookie login_nonce is set by GET /v2/login-form; we just need csrf from body
  return extractCsrf(res.body);
}

function jsonBody(res) {
  try { return res.json(); } catch (e) { return null; }
}

function isExpired(res) {
  const b = jsonBody(res);
  return res.status === 401 && b && b.error === 'expired';
}
function isSessionRevoked(res) {
  const b = jsonBody(res);
  return res.status === 401 && b && b.error === 'session';
}
function isDenied(res) {
  const b = jsonBody(res);
  return res.status === 401 && b && b.error === 'denied';
}

function sleepMs(ms) {
  const end = Date.now() + ms;
  while (Date.now() < end) { /* busy wait, k6 has no sleep in ms granularity */ }
}

// ---- journey -------------------------------------------------------------

export default function () {
  const user = `bench-${__VU}`;
  const password = 'bench';
  const cj = jar();

  const state = {
    csrf: null,
    session: null,
    cartId: null,
    cartEtag: null,
    orderId: null,
    orderKey: null,
  };

