  let res = http.get(`${BASE}/v2/login-form`, { jar: cj, redirects: 0 });
  check(res, { 'login-form 200': (r) => r.status === 200 });
  state.csrf = extractLoginNonce(res);
  check(state.csrf, { 'login csrf extracted': (v) => !!v });

  // 2. login
  res = http.post(`${BASE}/v2/login`, JSON.stringify({
    username: user, password, csrf: state.csrf,
  }), {
    jar: cj,
    redirects: 0,
    headers: { 'Content-Type': 'application/json' },
