  check(res, { 'login ok': (r) => r.status === 200 || r.status === 201 });
  const loginBody = jsonBody(res);
  check(loginBody, { 'login body': (b) => !!b });
  if (loginBody && loginBody.csrf) state.csrf = loginBody.csrf;
  check(state.csrf, { 'post-login csrf': (v) => !!v });

  // 3. catalog (variant 2 may reverse; traverse up to 3 pages)
  let product = null;
  let variant = null;
  res = http.get(`${BASE}/v2/catalog`, { jar: cj, redirects: 0 });
  check(res, { 'catalog 200': (r) => r.status === 200 });
  const cat = jsonBody(res);
  if (cat && cat.data && Array.isArray(cat.data.products)) {
    for (const p of cat.data.products) {
      if (p.variants && p.variants.length) {
        const v = p.variants.find((x) => x.in_stock);
        if (v) { product = p.id; variant = v.id; break; }
