    let next = '/v2/catalog/page';
    let pages = 0;
    while (next && pages < 3 && !product) {
      res = http.get(next.startsWith('http') ? next : `${BASE}${next}`, { jar: cj, redirects: 0 });
      check(res, { 'catalog page 200': (r) => r.status === 200 });
      const pb = jsonBody(res);
      if (pb && pb.product) {
        const p = pb.product;
        if (p.variants && p.variants.length) {
          const v = p.variants.find((x) => x.in_stock);
          if (v) { product = p.id; variant = v.id; }
        }
      }
      next = pb && pb.next ? pb.next : null;
      pages++;
    }
  }
  check(product, { 'product found': (v) => !!v });
  check(variant, { 'variant found': (v) => !!v });
  if (!product || !variant) return;

  // 4. challenge (grant_id)
  let grantId = null;
  res = http.get(`${BASE}/v2/challenge-form`, { jar: cj, redirects: 0 });
  check(res, { 'challenge-form 200': (r) => r.status === 200 });
  const chHtml = res.body || '';
  const actionMatch = /<form\b[^>]*\baction\s*=\s*["']?([^"'\s>]+)["']?/i.exec(chHtml);
  const challengeVal = extractCsrf(chHtml); // input[name=challenge] — reuse extractor pattern
  let challengeToken = null;
  {
    const re = /<input\b[^>]*\bname\s*=\s*["']?challenge["']?[^>]*>/gi;
    let m;
    while ((m = re.exec(chHtml)) !== null) {
      const v = /\bvalue\s*=\s*("([^"]*)"|'([^']*)'|([^\s>]+))/i.exec(m[0]);
      if (v) { challengeToken = v[2] !== undefined ? v[2] : v[3] !== undefined ? v[3] : v[4]; break; }
    }
  }
  check(actionMatch, { 'challenge action': (v) => !!v });
  check(challengeToken, { 'challenge token': (v) => !!v });
  if (actionMatch && challengeToken) {
    const action = actionMatch[1];
    res = http.post(action.startsWith('http') ? action : `${BASE}${action}`,
      JSON.stringify({ challenge: challengeToken }), {
        jar: cj, redirects: 0,
        headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': state.csrf },
      });
    if (res.status === 302) {
      const loc = res.headers['Location'] || res.headers['location'];
      if (loc) {
        res = http.get(loc.startsWith('http') ? loc : `${BASE}${loc}`, { jar: cj, redirects: 0 });
      }
    }
    const gb = jsonBody(res);
    if (gb && gb.csrf) state.csrf = gb.csrf;
    if (gb && gb.grant_id) grantId = gb.grant_id;
  }
  check(grantId, { 'grant_id obtained': (v) => !!v });

  // 5. create cart (grant_id once)
  const cartPayload = { product_id: product, variant_id: variant };
  if (grantId) cartPayload.grant_id = grantId;
  res = http.post(`${BASE}/v2/carts`, JSON.stringify(cartPayload), {
    jar: cj, redirects: 0,
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': state.csrf },
  });
  check(res, { 'cart created 201': (r) => r.status === 201 });
  const cb = jsonBody(res);
  if (cb && cb.csrf) state.csrf = cb.csrf;
  if (cb && cb.id) state.cartId = cb.id;
  state.cartEtag = res.headers['ETag'] || res.headers['etag'] || null;
  check(state.cartId, { 'cart id': (v) => !!v });
  if (!state.cartId) return;

  // 6. read cart for ETag
  res = http.get(`${BASE}/v2/carts/${state.cartId}`, { jar: cj, redirects: 0 });
  check(res, { 'cart read 200': (r) => r.status === 200 });
  state.cartEtag = res.headers['ETag'] || res.headers['etag'] || state.cartEtag;

  // 7. PATCH quantity with If-Match, retry once on 412
  const patchPayload = JSON.stringify({ quantity: 1 });
  let patched = false;
  for (let attempt = 0; attempt < 2 && !patched; attempt++) {
    const headers = {
      'Content-Type': 'application/json',
      'X-CSRF-Token': state.csrf,
    };
    if (state.cartEtag) headers['If-Match'] = state.cartEtag;
    res = http.patch(`${BASE}/v2/carts/${state.cartId}`, patchPayload, {
      jar: cj, redirects: 0, headers,
    });
    if (res.status === 412) {
      // re-read and retry same payload once
      const rr = http.get(`${BASE}/v2/carts/${state.cartId}`, { jar: cj, redirects: 0 });
      state.cartEtag = rr.headers['ETag'] || rr.headers['etag'] || state.cartEtag;
      continue;
    }
    if (isExpired(res)) {
