      const rn = http.post(`${BASE}/v2/session/renew`, '{}', {
        jar: cj, redirects: 0,
        headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': state.csrf },
      });
      const rb = jsonBody(rn);
      if (rb && rb.csrf) state.csrf = rb.csrf;
      http.post(`${BASE}/v2/carts/${state.cartId}/recover`, '{}', {
        jar: cj, redirects: 0,
        headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': state.csrf },
      });
      continue;
    }
    check(res, { 'patch ok': (r) => r.status === 200 || r.status === 204 });
    const pb = jsonBody(res);
    if (pb && pb.csrf) state.csrf = pb.csrf;
    state.cartEtag = res.headers['ETag'] || res.headers['etag'] || state.cartEtag;
    patched = true;
  }
  check(patched, { 'cart patched': (v) => v === true });

  // 8. reservation
  let reservationId = null;
  res = http.post(`${BASE}/v2/reservations`, JSON.stringify({ cart_id: state.cartId }), {
    jar: cj, redirects: 0,
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': state.csrf },
  });
  check(res, { 'reservation 202': (r) => r.status === 202 });
  const rb = jsonBody(res);
  if (rb && rb.csrf) state.csrf = rb.csrf;
