      jar: cj, redirects: 0,
      headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': state.csrf },
    });
    retries++;
  }
  check(res, { 'work ok': (r) => r.status === 200 });
  const wb = jsonBody(res);
  if (wb && wb.csrf) state.csrf = wb.csrf;
  check(wb, { 'work body ok': (b) => b && b.ok === true });
}
```

**Key behaviors implemented:**
- Fresh cookie jar per journey; login token extracted from `input[name=csrf]` with decoy/attribute-variant tolerance.
- Every mutating call (`login`, `challenge`, `carts`, `PATCH`, `reservations`, `orders`, `work`, `renew`, `recover`) sends `X-CSRF-Token` with the **latest** token, and refreshes it from each response body when `csrf` is present (retains previous otherwise).
- 302 login/challenge redirects handled with `redirects: 0` and a single manual GET of the dynamic `Location`.
- Catalog traversal bounded to 3 pages; `grant_id` passed exactly once to cart creation.
- PATCH uses `If-Match`; on 412 re-reads ETag and retries the same payload once.
- Reservation polled ≥50ms apart, ≤5 times; only `status=ready` yields `reservation_id`; `pending`/`failed` never reach checkout.
- Order uses a unique-per-cart `Idempotency-Key` stable across the single retry; `accepted:false` fails the check.
- `401 expired` triggers `renew` + `recover` + one retry of the interrupted op; `401 session`/`denied` are not silently retried.
- `/v2/work` handles scheduled 429 with `Retry-After` (≤4 retries); 500 fails the check.
- Two VUs × two iterations = 4 journeys, each with exactly one cart and one committed order.

