  const actionM = html.match(/<form\b[^>]*\baction\s*=\s*["']([^"']+)["']/i);
  const chalM = html.match(/<input\b[^>]*\bname\s*=\s*["']?challenge["']?[^>]*>/i);
  if (!actionM || !chalM) return null;
  const action = actionM[1];
  const vm = chalM[0].match(/\bvalue\s*=\s*["']([^"']*)["']/i);
  const challenge = vm ? vm[1] : '';
  const pr = http.post(action.startsWith('http') ? action : `${BASE}${action}`, JSON.stringify({ challenge }), {
    jar: cj,
    redirects: 0,
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
  });
  let loc = pr.headers['Location'] || pr.headers['location'];
  if (!loc) return null;
  const g = http.get(loc.startsWith('http') ? loc : `${BASE}${loc}`, { jar: cj, redirects: 0 });
  let body = {};
  try { body = g.json() || {}; } catch (e) {}
  return body.grant_id || null;
}

function renew(cj, csrf) {
  const r = http.post(`${BASE}/v2/session/renew`, '{}', {
    jar: cj,
    redirects: 0,
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
  });
  let body = {};
  try { body = r.json() || {}; } catch (e) {}
  return { status: r.status, csrf: body.csrf || csrf };
}

function recoverCart(cj, csrf, cartId) {
  const r = http.post(`${BASE}/v2/carts/${cartId}/recover`, '{}', {
    jar: cj,
    redirects: 0,
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
  });
  let body = {};
  try { body = r.json() || {}; } catch (e) {}
  return { status: r.status, csrf: body.csrf || csrf };
}

function isExpired(r) {
  if (r.status !== 401) return false;
  try {
    const b = r.json() || {};
    return b.error === 'expired' || b.error === 'session';
  } catch (e) {
    return false;
  }
}

function isDenied(r) {
  if (r.status !== 401) return false;
  try {
    const b = r.json() || {};
    return b.error === 'denied';
  } catch (e) {
    return false;
  }
}

function createCart(cj, csrf, prod, grantId) {
  const payload = { product_id: prod.product_id, variant_id: prod.variant_id };
  if (grantId) payload.grant_id = grantId;
  const r = http.post(`${BASE}/v2/carts`, JSON.stringify(payload), {
    jar: cj,
    redirects: 0,
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
  });
  let body = {};
  try { body = r.json() || {}; } catch (e) {}
  return { status: r.status, body, etag: r.headers['Etag'] || r.headers['etag'] };
}

function patchCart(cj, csrf, cartId, etag, qty) {
  const r = http.patch(`${BASE}/v2/carts/${cartId}`, JSON.stringify({ quantity: qty }), {
    jar: cj,
    redirects: 0,
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
      'If-Match': etag || '',
    },
  });
  let body = {};
  try { body = r.json() || {}; } catch (e) {}
  return { status: r.status, body, etag: r.headers['Etag'] || r.headers['etag'] };
}

function getCart(cj, cartId) {
  const r = http.get(`${BASE}/v2/carts/${cartId}`, { jar: cj, redirects: 0 });
  return { status: r.status, etag: r.headers['Etag'] || r.headers['etag'] };
}

function reserve(cj, csrf, cartId) {
  const r = http.post(`${BASE}/v2/reservations`, JSON.stringify({ cart_id: cartId }), {
    jar: cj,
    redirects: 0,
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
  });
  let body = {};
  try { body = r.json() || {}; } catch (e) {}
  return { status: r.status, body };
}

function pollReservation(cj, statusUrl) {
  for (let i = 0; i < 5; i++) {
    const r = http.get(statusUrl.startsWith('http') ? statusUrl : `${BASE}${statusUrl}`, { jar: cj, redirects: 0 });
    let body = {};
    try { body = r.json() || {}; } catch (e) {}
    if (body.status === 'ready') return body.reservation_id || null;
    if (body.status === 'failed') return null;
    // sleep 60ms
    const t = Date.now();
    while (Date.now() - t < 60) { /* busy wait */ }
  }
  return null;
}

function placeOrder(cj, csrf, cartId, reservationId, idemKey, etag) {
  const payload = { cart_id: cartId };
  if (reservationId) payload.reservation_id = reservationId;
  const headers = {
    'Content-Type': 'application/json',
    'X-CSRF-Token': csrf,
    'Idempotency-Key': idemKey,
  };
  if (etag) headers['If-Match'] = etag;
  const r = http.post(`${BASE}/v2/orders`, JSON.stringify(payload), {
    jar: cj,
    redirects: 0,
    headers,
  });
  let body = {};
  try { body = r.json() || {}; } catch (e) {}
  return { status: r.status, body };
}

export default function () {
  const user = `bench-${__VU}`;
  const cj = jar();

  let csrf = login(cj, user);
  check(csrf, { 'logged in': (v) => !!v });

  const prod = pickProduct(cj);
  check(prod, { 'product found': (v) => !!v });
  if (!prod) return;

  // challenge for grant
  let grantId = solveChallenge(cj, csrf);

  let cart = createCart(cj, csrf, prod, grantId);
  if (isExpired({ status: cart.status, json: () => cart.body })) {
    const rn = renew(cj, csrf);
    csrf = rn.csrf;
    if (rn.status === 401) {
      csrf = login(cj, user);
    }
    cart = createCart(cj, csrf, prod, grantId);
  }
  check(cart, { 'cart created': (c) => c.status === 201 && c.body.id });
  if (cart.status !== 201 || !cart.body.id) return;
  const cartId = cart.body.id;
  if (cart.body.csrf) csrf = cart.body.csrf;
  let etag = cart.etag;

  // patch quantity
  let patched = patchCart(cj, csrf, cartId, etag, 1);
  if (patched.status === 412) {
    const g = getCart(cj, cartId);
    etag = g.etag;
    patched = patchCart(cj, csrf, cartId, etag, 1);
  }
  if (isExpired({ status: patched.status, json: () => patched.body })) {
    const rn = renew(cj, csrf);
    csrf = rn.csrf;
    if (rn.status === 401) {
      csrf = login(cj, user);
      recoverCart(cj, csrf, cartId);
    } else {
      recoverCart(cj, csrf, cartId);
    }
    patched = patchCart(cj, csrf, cartId, etag, 1);
    if (patched.status === 412) {
      const g = getCart(cj, cartId);
      etag = g.etag;
      patched = patchCart(cj, csrf, cartId, etag, 1);
    }
  }
  if (patched.body && patched.body.csrf) csrf = patched.body.csrf;
  if (patched.etag) etag = patched.etag;
  check(patched, { 'cart patched': (p) => p.status === 200 || p.status === 204 });

  // reservation
  let res = reserve(cj, csrf, cartId);
  if (isExpired({ status: res.status, json: () => res.body })) {
    const rn = renew(cj, csrf);
    csrf = rn.csrf;
    if (rn.status === 401) {
      csrf = login(cj, user);
    }
    recoverCart(cj, csrf, cartId);
    res = reserve(cj, csrf, cartId);
  }
  if (res.body && res.body.csrf) csrf = res.body.csrf;
  let reservationId = null;
  if (res.status === 202 && res.body.status_url) {
    reservationId = pollReservation(cj, res.body.status_url);
  }
  check(reservationId, { 'reservation ready': (v) => !!v });

  // order
  const idemKey = `idem-${user}-${cartId}`;
  let order = placeOrder(cj, csrf, cartId, reservationId, idemKey, etag);
  if (isExpired({ status: order.status, json: () => order.body })) {
    const rn = renew(cj, csrf);
    csrf = rn.csrf;
    if (rn.status === 401) {
      csrf = login(cj, user);
    }
    recoverCart(cj, csrf, cartId);
    order = placeOrder(cj, csrf, cartId, reservationId, idemKey, etag);
  }
  check(order, {
    'order accepted': (o) => o.status === 201 && o.body.accepted === true && !!o.body.id,
  });
}
