import http from 'k6/http';
import { check } from 'k6';

const BASE = __ENV.BASE_URL || 'http://127.0.0.1:8000';

export const options = {
  scenarios: {
    reservation: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '120s',
    },
  },
  thresholds: {
    checks: ['rate==1'],
  },
};

const PROFILES = [
  { job_polls: 2, poll_interval: 0.02 },
  { job_polls: 3, poll_interval: 0.02, html_layout: 1, reverse_catalog: true },
];

function sleep(ms) {
  const end = Date.now() + ms;
  while (Date.now() < end) {}
}

function parseCsrfFromForm(body) {
  // input[name=csrf] with possible attribute variants / decoys
  const re = /<input\b[^>]*\bname\s*=\s*["']?csrf["']?[^>]*>/gi;
  let m;
  while ((m = re.exec(body)) !== null) {
    const tag = m[0];
    const vm = tag.match(/\bvalue\s*=\s*["']([^"']*)["']/i);
    if (vm) return vm[1];
  }
  return null;
}

function extractLocation(res) {
  return res.headers['Location'] || res.headers['location'] || null;
}

function getJson(res) {
  try { return res.json(); } catch (e) { return null; }
}

function login(username, password) {
  const jar = http.cookieJar();
  jar.clear(BASE);

  const formRes = http.get(`${BASE}/v2/login-form`, { redirects: 0 });
  check(formRes, { 'login-form 200': (r) => r.status === 200 });
  const csrf = parseCsrfFromForm(formRes.body || '');
  check(csrf, { 'login csrf found': (v) => !!v });

  const loginRes = http.post(`${BASE}/v2/login`, JSON.stringify({
    username, password, csrf,
  }), {
    headers: { 'Content-Type': 'application/json' },
    redirects: 0,
  });

  let token = csrf;
  if (loginRes.status === 302) {
    const loc = extractLocation(loginRes);
    if (loc) {
      const follow = http.get(loc.startsWith('http') ? loc : `${BASE}${loc}`, { redirects: 0 });
      const j = getJson(follow);
      if (j && j.csrf) token = j.csrf;
    }
  } else {
    const j = getJson(loginRes);
    if (j && j.csrf) token = j.csrf;
  }
  check(loginRes, { 'login ok': (r) => r.status === 200 || r.status === 302 });
  return token;
}

function fetchCatalog(profile) {
  const products = [];
  const first = http.get(`${BASE}/v2/catalog`, { redirects: 0 });
  check(first, { 'catalog 200': (r) => r.status === 200 });
  const j = getJson(first);
  if (j && j.data && Array.isArray(j.data.products)) {
    for (const p of j.data.products) products.push(p);
  }
  let next = j && j.next;
  let pages = 0;
  while (next && pages < 3) {
    const url = next.startsWith('http') ? next : `${BASE}${next}`;
    const r = http.get(url, { redirects: 0 });
    if (r.status !== 200) break;
    const pj = getJson(r);
    if (pj && pj.data && Array.isArray(pj.data.products)) {
      for (const p of pj.data.products) products.push(p);
    } else if (pj && pj.data && pj.data.product) {
      products.push(pj.data.product);
    } else if (pj && pj.product) {
      products.push(pj.product);
    }
    next = pj && pj.next;
    pages++;
  }
  if (profile && profile.reverse_catalog) products.reverse();
  return products;
}

function pickVariant(products) {
  for (const p of products) {
    if (!p || !Array.isArray(p.variants)) continue;
    for (const v of p.variants) {
      if (v && v.in_stock) return { product_id: p.id, variant_id: v.id };
    }
  }
  return null;
}

function solveChallenge(csrf) {
  const formRes = http.get(`${BASE}/v2/challenge-form`, { redirects: 0 });
  if (formRes.status !== 200) return { grant_id: null, csrf };
  const body = formRes.body || '';
  const actionMatch = body.match(/<form\b[^>]*\baction\s*=\s*["']([^"']+)["']/i);
  const challengeMatch = body.match(/<input\b[^>]*\bname\s*=\s*["']?challenge["']?[^>]*>/i);
  let challengeVal = null;
  if (challengeMatch) {
    const vm = challengeMatch[0].match(/\bvalue\s*=\s*["']([^"']*)["']/i);
    if (vm) challengeVal = vm[1];
  }
  if (!actionMatch || !challengeVal) return { grant_id: null, csrf };
  const action = actionMatch[1].startsWith('http') ? actionMatch[1] : `${BASE}${actionMatch[1]}`;
  const postRes = http.post(action, JSON.stringify({ challenge: challengeVal }), {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
    redirects: 0,
  });
  let newCsrf = csrf;
  if (postRes.status === 302) {
    const loc = extractLocation(postRes);
    if (loc) {
      const follow = http.get(loc.startsWith('http') ? loc : `${BASE}${loc}`, { redirects: 0 });
      const j = getJson(follow);
      if (j) {
        if (j.csrf) newCsrf = j.csrf;
        if (j.grant_id) return { grant_id: j.grant_id, csrf: newCsrf };
      }
    }
  }
  return { grant_id: null, csrf: newCsrf };
}

function createCart(csrf, product_id, variant_id, grant_id) {
  const payload = { product_id, variant_id };
  if (grant_id) payload.grant_id = grant_id;
  const res = http.post(`${BASE}/v2/carts`, JSON.stringify(payload), {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
    redirects: 0,
  });
  check(res, { 'cart 201': (r) => r.status === 201 });
  const j = getJson(res);
  const etag = res.headers['Etag'] || res.headers['ETag'] || res.headers['etag'];
  return { id: j && j.id, csrf: (j && j.csrf) || csrf, etag };
}

function patchCart(csrf, cartId, etag, quantity) {
  const url = `${BASE}/v2/carts/${cartId}`;
  const headers = {
    'Content-Type': 'application/json',
    'X-CSRF-Token': csrf,
    'If-Match': etag || '',
  };
  let res = http.patch(url, JSON.stringify({ quantity }), { headers, redirects: 0 });
  if (res.status === 412) {
    const reread = http.get(url, { redirects: 0 });
    const newEtag = reread.headers['Etag'] || reread.headers['ETag'] || reread.headers['etag'];
    headers['If-Match'] = newEtag || '';
    res = http.patch(url, JSON.stringify({ quantity }), { headers, redirects: 0 });
  }
  check(res, { 'patch ok': (r) => r.status === 200 || r.status === 204 });
  const j = getJson(res);
  return { csrf: (j && j.csrf) || csrf, etag: res.headers['Etag'] || res.headers['ETag'] || res.headers['etag'] };
}

function startReservation(csrf, cartId) {
  const res = http.post(`${BASE}/v2/reservations`, JSON.stringify({ cart_id: cartId }), {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
    redirects: 0,
  });
  check(res, { 'reservation 202': (r) => r.status === 202 });
  const j = getJson(res);
  return { status_url: j && j.status_url, csrf: (j && j.csrf) || csrf };
}

function pollReservation(csrf, statusUrl, profile) {
  const maxPolls = Math.min(5, profile.job_polls);
  const intervalMs = Math.max(50, Math.round((profile.poll_interval || 0.02) * 1000));
  let lastCsrf = csrf;
  let reservationId = null;
  let finalStatus = null;
  for (let i = 0; i < maxPolls; i++) {
    if (i > 0) sleep(intervalMs);
    const url = statusUrl.startsWith('http') ? statusUrl : `${BASE}${statusUrl}`;
    const res = http.get(url, {
      headers: { 'X-CSRF-Token': lastCsrf },
      redirects: 0,
    });
    const j = getJson(res);
    if (j && j.csrf) lastCsrf = j.csrf;
    const status = j && j.status;
    finalStatus = status;
    if (status === 'ready') {
      reservationId = j.reservation_id;
      break;
    }
    if (status === 'failed') break;
  }
  return { reservation_id: reservationId, status: finalStatus, csrf: lastCsrf };
}

function checkout(csrf, cartId, etag, reservationId) {
  const payload = { cart_id: cartId };
  if (reservationId) payload.reservation_id = reservationId;
  const headers = {
    'Content-Type': 'application/json',
    'X-CSRF-Token': csrf,
    'Idempotency-Key': `idem-${cartId}-${Date.now()}`,
  };
  if (etag) headers['If-Match'] = etag;
  const res = http.post(`${BASE}/v2/orders`, JSON.stringify(payload), { headers, redirects: 0 });
  const j = getJson(res);
  const ok = res.status === 201 && j && j.accepted === true;
  check(res, { 'order accepted': () => ok });
  return { ok, csrf: (j && j.csrf) || csrf };
}

export default function () {
  const vu = __VU;
  const iter = __ITER;
  const profile = PROFILES[(vu + iter) % PROFILES.length];
  const username = `bench-${((vu - 1) % 16) + 1}`;
  const password = 'bench';

  let csrf = login(username, password);

  const products = fetchCatalog(profile);
  const pick = pickVariant(products);
  check(pick, { 'variant picked': (v) => !!v });
  if (!pick) return;

  const challenge = solveChallenge(csrf);
  csrf = challenge.csrf;

  const cart = createCart(csrf, pick.product_id, pick.variant_id, challenge.grant_id);
  csrf = cart.csrf;
  check(cart.id, { 'cart id': (v) => !!v });
  if (!cart.id) return;

  const patched = patchCart(csrf, cart.id, cart.etag, 1);
  csrf = patched.csrf;

  const reservation = startReservation(csrf, cart.id);
  csrf = reservation.csrf;
  check(reservation.status_url, { 'status_url': (v) => !!v });
  if (!reservation.status_url) return;

  const polled = pollReservation(csrf, reservation.status_url, profile);
  csrf = polled.csrf;

  if (polled.status !== 'ready' || !polled.reservation_id) {
    check(null, { 'reservation ready': () => false });
    return;
  }

  checkout(csrf, cart.id, patched.etag, polled.reservation_id);
}
