  },
};

const BASE = __ENV.BASE_URL || 'http://127.0.0.1:8000';

function jar() {
  return http.cookieJar();
}

function parseCsrfFromForm(body) {
  // input[name=csrf] with possible attribute variants / decoys
  const re = /<input\b[^>]*\bname\s*=\s*["']?csrf["']?[^>]*>/gi;
  let m;
  while ((m = re.exec(body)) !== null) {
    const tag = m[0];
    const vm = tag.match(/\bvalue\s*=\s*["']([^"']*)["']/i);
    if (vm) return vm[1];
  }
  return null;
}

function parseChallengeForm(body) {
  const actionM = body.match(/<form\b[^>]*\baction\s*=\s*["']([^"']+)["']/i);
  const inputM = body.match(/<input\b[^>]*\bname\s*=\s*["']?challenge["']?[^>]*>/i);
  let value = null;
  if (inputM) {
    const vm = inputM[0].match(/\bvalue\s*=\s*["']([^"']*)["']/i);
    if (vm) value = vm[1];
  }
  return { action: actionM ? actionM[1] : null, value };
}

function absUrl(u) {
  if (!u) return null;
  if (/^https?:\/\//i.test(u)) return u;
  if (u.startsWith('/')) return BASE + u;
  return BASE + '/' + u;
}

function getJson(res) {
  try { return res.json(); } catch (e) { return null; }
}

function login(jarRef) {
  const formRes = http.get(BASE + '/v2/login-form', { jar: jarRef, redirects: 0 });
  check(formRes, { 'login-form 200': (r) => r.status === 200 });
  const csrf = parseCsrfFromForm(formRes.body || '');
  check(csrf, { 'login csrf extracted': (v) => !!v });
  const loginRes = http.post(
    BASE + '/v2/login',
    JSON.stringify({ username: 'bench-1', password: 'bench', csrf }),
    { jar: jarRef, redirects: 0, headers: { 'Content-Type': 'application/json' } }
  );
  let ok = check(loginRes, { 'login 200/302': (r) => r.status === 200 || r.status === 302 });
  if (loginRes.status === 302) {
    const loc = loginRes.headers['Location'] || loginRes.headers['location'];
    if (loc) {
      const follow = http.get(absUrl(loc), { jar: jarRef, redirects: 0 });
      check(follow, { 'login redirect followed': (r) => r.status >= 200 && r.status < 400 });
    }
  }
  const body = getJson(loginRes);
  let token = body && body.csrf ? body.csrf : null;
  if (!token) {
    // try to re-read from a fresh form
    const f2 = http.get(BASE + '/v2/login-form', { jar: jarRef, redirects: 0 });
    token = parseCsrfFromForm(f2.body || '');
  }
  check(token, { 'session csrf present': (v) => !!v });
  return token;
}

function renew(jarRef, csrf) {
  const r = http.post(BASE + '/v2/session/renew', '{}', {
    jar: jarRef,
    redirects: 0,
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
  });
  const b = getJson(r);
  return b && b.csrf ? b.csrf : csrf;
}

function recoverCart(jarRef, csrf, cartId) {
  const r = http.post(BASE + '/v2/carts/' + cartId + '/recover', '{}', {
    jar: jarRef,
    redirects: 0,
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
  });
  const b = getJson(r);
  return b && b.csrf ? b.csrf : csrf;
}

function pickProduct(jarRef, csrf, reverse) {
  // Try catalog first
  const cat = http.get(BASE + '/v2/catalog', { jar: jarRef, redirects: 0 });
  check(cat, { 'catalog 200': (r) => r.status === 200 });
  const cb = getJson(cat);
  let products = cb && cb.data && cb.data.products ? cb.data.products : [];
  if (reverse) products = products.slice().reverse();
  for (const p of products) {
    const variants = p.variants || [];
    const vs = reverse ? variants.slice().reverse() : variants;
    for (const v of vs) {
      if (v.in_stock) return { product_id: p.id, variant_id: v.id };
    }
  }
  // Fallback: paginated catalog
  let url = BASE + '/v2/catalog/page';
  for (let i = 0; i < 3 && url; i++) {
