function patchQuantity(jarRef, csrf, cartId, etag, qty) {
  const doPatch = (et) => http.patch(
    BASE + '/v2/carts/' + cartId,
    JSON.stringify({ quantity: qty }),
    {
      jar: jarRef,
      redirects: 0,
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': csrf,
        'If-Match': et || '',
      },
