    const re = http.get(BASE + '/v2/carts/' + cartId, { jar: jarRef, redirects: 0 });
    const newEtag = re.headers['Etag'] || re.headers['ETag'] || re.headers['etag'] || null;
    r = doPatch(newEtag);
