  check(r, { 'cart patch ok': (res) => res.status >= 200 && res.status < 300 });
  const b = getJson(r);
  const newCsrf = b && b.csrf ? b.csrf : csrf;
  const newEtag = r.headers['Etag'] || r.headers['ETag'] || r.headers['etag'] || etag;
