    const s = http.get(absUrl(status_url), { jar: jarRef, redirects: 0 });
    const sb = getJson(s);
    const status = sb && sb.status ? sb.status : null;
    if (sb && sb.csrf) newCsrf = sb.csrf;
    if (status === 'ready') {
      const rid = sb.reservation_id || null;
      check(rid, { 'reservation_id present': (v) => !!v });
      return { reservation_id: rid, csrf: newCsrf };
    }
    if (status === 'failed') {
      check(false, { 'reservation not failed': () => false });
      return { reservation_id: null, csrf: newCsrf };
    }
