  return { reservation_id: null, csrf: newCsrf };
}

function placeOrder(jarRef, csrf, cartId, reservation_id, etag) {
  const payload = { cart_id: cartId };
  if (reservation_id) payload.reservation_id = reservation_id;
  const idem = 'idem-' + cartId;
  const headers = {
    'Content-Type': 'application/json',
    'X-CSRF-Token': csrf,
    'Idempotency-Key': idem,
  };
