    jar: jarRef,
    redirects: 0,
    headers,
  });
  const b = getJson(r);
  const accepted = b && b.accepted === true;
  check(r, { 'order 201': (res) => res.status === 201 });
  check(accepted, { 'order accepted true': (v) => v === true });
  return { csrf: b && b.csrf ? b.csrf : csrf, accepted };
}

function businessWork(jarRef, csrf) {
  for (let i = 0; i < 4; i++) {
    const r = http.post(BASE + '/v2/work', '{}', {
      jar: jarRef,
      redirects: 0,
      headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
    });
    if (r.status === 429) {
      const ra = r.headers['Retry-After'] || r.headers['retry-after'];
      const wait = ra ? parseInt(ra, 10) * 1000 : 1000;
      const start = Date.now();
      while (Date.now() - start < wait) { /* spin */ }
      continue;
    }
    check(r, { 'work 200': (res) => res.status === 200 });
    const b = getJson(r);
    check(b && b.ok === true, { 'work ok true': (v) => v === true });
