export default function () {
  const jarRef = jar();
  let csrf = login(jarRef);
  if (!csrf) return;

  const picked = pickProduct(jarRef, csrf, false);
  check(picked, { 'product picked': (v) => !!v });
  if (!picked) return;

  const grant = obtainGrant(jarRef, csrf);
  csrf = grant.csrf;

  const cart = createCart(jarRef, csrf, picked.product_id, picked.variant_id, grant.grant_id);
  csrf = cart.csrf;
  check(cart.id, { 'cart id present': (v) => !!v });
  if (!cart.id) return;

  const patched = patchQuantity(jarRef, csrf, cart.id, cart.etag, 1);
  csrf = patched.csrf;

  const resv = reserve(jarRef, csrf, cart.id);
  csrf = resv.csrf;

  const order = placeOrder(jarRef, csrf, cart.id, resv.reservation_id, patched.etag);
  csrf = order.csrf;

  businessWork(jarRef, csrf);
}
