```javascript
import http from 'k6/http';
import { check, sleep } from 'k6';
import { SharedArray } from 'k6/data';
import exec from 'k6/execution';

const BASE = __ENV.BASE_URL || 'http://127.0.0.1:8000';

// Two users deliberately share the SAME account ("bench").
// Per-thread CSV delay staggers subsequent work.
const USERS = new SharedArray('users', function () {
  return [
    { username: 'bench', password: 'bench', quantity: 2, delay: 0 },
    { username: 'bench', password: 'bench', quantity: 3, delay: 500 },
  ];
});

export const options = {
  scenarios: {
    shared_account: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 1,
      maxDuration: '120s',
    },
  },
  thresholds: {
    checks: ['rate==1'],
  },
};

// ---------- helpers ----------

function parseSetCookies(res) {
  // k6 exposes cookies via res.cookies; we keep a simple jar object.
  const jar = {};
  const c = res.cookies || {};
  for (const name of Object.keys(c)) {
    if (c[name] && c[name].length) jar[name] = c[name][0].value;
  }
  return jar;
}

function mergeJar(jar, res) {
  const c = res.cookies || {};
  for (const name of Object.keys(c)) {
    if (c[name] && c[name].length) jar[name] = c[name][0].value;
  }
}

function cookieHeader(jar) {
  return Object.keys(jar).map((k) => `${k}=${jar[k]}`).join('; ');
}

function extractCsrfFromForm(html) {
  // input[name=csrf] mixed with decoys / attribute variants.
  // Accept value before or after name, single or double quotes.
  const patterns = [
    /<input[^>]*name=["']csrf["'][^>]*value=["']([^"']+)["']/i,
    /<input[^>]*value=["']([^"']+)["'][^>]*name=["']csrf["']/i,
  ];
  for (const re of patterns) {
    const m = html.match(re);
    if (m) return m[1];
  }
  return null;
}

function extractChallengeAction(html) {
  const m = html.match(/<form[^>]*action=["']([^"']*\/v2\/challenges\/[^"']+)["']/i);
  return m ? m[1] : null;
}

function extractChallengeInput(html) {
  const patterns = [
    /<input[^>]*name=["']challenge["'][^>]*value=["']([^"']*)["']/i,
    /<input[^>]*value=["']([^"']*)["'][^>]*name=["']challenge["']/i,
  ];
  for (const re of patterns) {
    const m = html.match(re);
    if (m) return m[1];
  }
  return null;
}

function absUrl(u) {
  if (!u) return null;
  if (u.startsWith('http')) return u;
  if (u.startsWith('/')) return BASE + u;
  return BASE + '/' + u;
}

function isExpired(res) {
  try {
    const b = res.json();
    return res.status === 401 && b && b.error === 'expired';
  } catch (e) {
    return false;
  }
}

function isRevoked(res) {
  try {
    const b = res.json();
    return res.status === 401 && b && b.error === 'session';
  } catch (e) {
    return false;
  }
}

function isDenied(res) {
  try {
    const b = res.json();
    return res.status === 401 && b && b.error === 'denied';
  } catch (e) {
    return false;
  }
}

// ---------- session state ----------

function newSession() {
  return {
    jar: {},
    csrf: null,
    user: null,
    loggedIn: false,
    loginCount: 0,
  };
}

function headers(sess, extra) {
  const h = {
    'Content-Type': 'application/json',
    'Accept': 'application/json',
  };
  const ch = cookieHeader(sess.jar);
  if (ch) h['Cookie'] = ch;
  if (sess.csrf) h['X-CSRF-Token'] = sess.csrf;
  if (extra) Object.assign(h, extra);
  return h;
}

// ---------- login flow ----------

function doLogin(sess) {
  // 1. GET login form
  const formRes = http.get(`${BASE}/v2/login-form`, {
    headers: { 'Cookie': cookieHeader(sess.jar) },
    redirects: 0,
  });
  mergeJar(sess.jar, formRes);
  check(formRes, { 'login-form 200': (r) => r.status === 200 });
  const csrf = extractCsrfFromForm(formRes.body || '');
  check(csrf, { 'login-form csrf found': (v) => !!v });
  if (!csrf) return false;

  // 2. POST login
  const loginRes = http.post(
    `${BASE}/v2/login`,
    JSON.stringify({ username: sess.username, password: sess.password, csrf }),
    { headers: headers(sess, { 'Cookie': cookieHeader(sess.jar) }), redirects: 0 }
  );
  mergeJar(sess.jar, loginRes);

  let ok = false;
  if (loginRes.status === 302) {
    const loc = loginRes.headers['Location'] || loginRes.headers['location'];
    if (loc) {
      const follow = http.get(absUrl(loc), {
        headers: { 'Cookie': cookieHeader(sess.jar) },
        redirects: 0,
      });
      mergeJar(sess.jar, follow);
      ok = follow.status >= 200 && follow.status < 400;
    }
  } else if (loginRes.status === 200) {
    ok = true;
  }

  check(loginRes, { 'login accepted': () => ok });
  if (!ok) return false;

  // 3. Extract csrf/user from login response body if present
  try {
    const b = loginRes.json();
    if (b && b.csrf) sess.csrf = b.csrf;
    if (b && b.user) sess.user = b.user;
  } catch (e) { /* body may be empty on 302 */ }

  // If csrf not in body, re-fetch form to obtain a fresh csrf for authenticated calls.
  if (!sess.csrf) {
    const f2 = http.get(`${BASE}/v2/login-form`, {
      headers: { 'Cookie': cookieHeader(sess.jar) },
      redirects: 0,
    });
    mergeJar(sess.jar, f2);
    const c2 = extractCsrfFromForm(f2.body || '');
    if (c2) sess.csrf = c2;
  }

  sess.loggedIn = true;
  sess.loginCount += 1;
  return true;
}

// ---------- recovery ----------

function renew(sess) {
  const res = http.post(`${BASE}/v2/session/renew`, '{}', {
    headers: headers(sess),
    redirects: 0,
  });
  mergeJar(sess.jar, res);
  if (res.status === 200) {
    try {
      const b = res.json();
      if (b && b.csrf) sess.csrf = b.csrf;
    } catch (e) { /* ignore */ }
    return true;
  }
  return false;
}

function recoverCart(sess, cartId) {
  if (!cartId) return true;
  const res = http.post(`${BASE}/v2/carts/${cartId}/recover`, '{}', {
    headers: headers(sess),
    redirects: 0,
  });
  mergeJar(sess.jar, res);
  if (res.status === 200 || res.status === 204) {
    try {
      const b = res.json();
      if (b && b.csrf) sess.csrf = b.csrf;
    } catch (e) { /* ignore */ }
    return true;
  }
  return false;
}

// Handle a 401 on an authenticated call. Returns true if recovered.
// Bounded: one renew attempt, one re-login attempt, one cart recover.
function handle401(sess, res, cartId) {
  if (isDenied(res)) {
    check(res, { 'denied is not expiry': () => false });
    return false;
  }
  if (isExpired(res)) {
    if (renew(sess)) {
      if (cartId) recoverCart(sess, cartId);
      return true;
    }
