  if (isRevoked(res) || isExpired(res)) {
    // deliberate recovery: fresh form/login, then recover cart
    sess.loggedIn = false;
    sess.csrf = null;
    const ok = doLogin(sess);
    if (ok && cartId) recoverCart(sess, cartId);
    return ok;
  }
  return false;
}

// ---------- catalog ----------

function fetchCatalog(sess) {
  const res = http.get(`${BASE}/v2/catalog`, {
    headers: headers(sess),
    redirects: 0,
  });
  mergeJar(sess.jar, res);
  if (res.status === 401) {
    if (handle401(sess, res, null)) {
      return fetchCatalog(sess);
    }
    return null;
  }
  check(res, { 'catalog 200': (r) => r.status === 200 });
  try {
    const b = res.json();
    return b && b.data && b.data.products ? b.data.products : null;
  } catch (e) {
    return null;
  }
}

function pickProduct(products) {
  if (!products || !products.length) return null;
  for (const p of products) {
    if (p.variants && p.variants.length) {
      for (const v of p.variants) {
        if (v.in_stock) return { product_id: p.id, variant_id: v.id };
      }
    }
  }
