}

// ---------- challenge ----------

function solveChallenge(sess) {
  const formRes = http.get(`${BASE}/v2/challenge-form`, {
    headers: headers(sess),
    redirects: 0,
  });
  mergeJar(sess.jar, formRes);
  if (formRes.status === 401) {
    if (handle401(sess, formRes, null)) return solveChallenge(sess);
    return null;
