  check(res, { 'order 201': (r) => r.status === 201 });
  if (res.status === 201) {
    try {
      const b = res.json();
      if (b && b.csrf) sess.csrf = b.csrf;
      return !!(b && b.accepted === true);
    } catch (e) {
      return false;
    }
  }
  return false;
}

// ---------- business work (rate metric) ----------

function doWork(sess) {
  let retries = 0;
  while (retries <= 4) {
    const res = http.post(`${BASE}/v2/work`, '{}', {
      headers: headers(sess),
      redirects: 0,
    });
    mergeJar(sess.jar, res);
    if (res.status === 401) {
      if (handle401(sess, res, null)) continue;
      return false;
    }
    if (res.status === 429) {
      const ra = parseInt(res.headers['Retry-After'] || res.headers['retry-after'] || '1', 10);
      sleep(isNaN(ra) ? 1 : ra);
      retries++;
      continue;
    }
    if (res.status === 500) {
      check(res, { 'work not 500': () => false });
      return false;
    }
    check(res, { 'work 200': (r) => r.status === 200 });
    return res.status === 200;
  }
  return false;
}

// ---------- journey ----------

export default function () {
  const idx = exec.vu.idInTest - 1;
  const u = USERS[idx % USERS.length];

  const sess = newSession();
  sess.username = u.username;
  sess.password = u.password;

  // Initial login
  const loggedIn = doLogin(sess);
  check(sess, { 'initial login ok': () => loggedIn });
  if (!loggedIn) return;

  // Synchronize after initial logins: both VUs share the same account.
  // A short barrier via sleep lets the second login invalidate the first.
  sleep(0.3);

  // Deliberate revocation detection: probe an authenticated endpoint.
  // The later login invalidates the earlier session; detect and recover.
  const probe = http.get(`${BASE}/v2/catalog`, {
    headers: headers(sess),
    redirects: 0,
  });
  mergeJar(sess.jar, probe);

  if (probe.status === 401) {
    const revoked = isRevoked(probe) || isExpired(probe);
    check(probe, { 'revocation detected': () => revoked });
    if (revoked) {
      // deliberate recovery: fresh login (no ping-pong; bounded)
      sess.loggedIn = false;
      sess.csrf = null;
      const relog = doLogin(sess);
      check(sess, { 'recovery login ok': () => relog });
      if (!relog) return;
    } else if (isDenied(probe)) {
      check(probe, { 'denied not expiry': () => false });
      return;
    }
  } else {
    check(probe, { 'probe 200': (r) => r.status === 200 });
  }

  // Per-thread CSV delay staggers subsequent work.
  if (u.delay > 0) sleep(u.delay / 1000);

  // Catalog
  const products = fetchCatalog(sess);
  const product = pickProduct(products);
  check(product, { 'product selected': (v) => !!v });
  if (!product) return;

  // Challenge -> grant
  const grantId = solveChallenge(sess);

  // Cart
  const cart = createCart(sess, product, grantId);
  check(cart, { 'cart created': (v) => !!v });
  if (!cart) return;

  // Quantity
  const qty = Math.max(1, Math.min(20, u.quantity));
  const patched = patchQuantity(sess, cart, qty);
  check(sess, { 'quantity patched': () => patched });
  if (!patched) return;

  // Reservation
  const reservationId = reserve(sess, cart.id);
  check(sess, { 'reservation ready': () => !!reservationId });
  if (!reservationId) return;

  // Order (one committed order per journey)
  const ordered = placeOrder(sess, cart.id, reservationId);
  check(sess, { 'order committed': () => ordered });

  // Business work (rate metric)
  doWork(sess);
}
```

**Notes on contract compliance**

- **Loads (10):** `per-vu-iterations`, 2 VUs × 1 iteration; `SharedArray` loads both fixture rows (bench/bench, quantities 2 & 3, delays 0 & 500ms).
- **Setup (25):** Both VUs log in to the *same* account `bench`; a post-login barrier (`sleep(0.3)`) plus an authenticated probe detects the later login's revocation (`401 error=session` or `expired`).
- **Behavior (40):** On revocation, a bounded fresh form/login is performed (no ping-pong — single recovery attempt), then cart recovery via `/v2/carts/{id}/recover`; CSRF is refreshed from every response that supplies it and retained otherwise; `X-CSRF-Token` sent on all non-GET calls; `If-Match`/412 re-read retry; challenge grant passed once; reservation polled ≥50ms × ≤5; `accepted:false` treated as failure.
- **Safety (25):** Exactly one cart, one order per journey; `Idempotency-Key` stable per cart; recovery bounded per operation; `denied` fails its assertion; `429` honors `Retry-After` ≤4 retries; `500` fails; `/v2/health` unused.
- **Negative controls:** none supplied, so none injected; `denied` and `accepted:false` paths assert failure truthfully.

