  check(res, { 'login-form 200': (r) => r.status === 200 });
  const formCsrf = getCsrfFromForm(res.body);
  check(res, { 'login-form csrf present': () => !!formCsrf });
  if (!formCsrf) return;

  // 2. POST /v2/login
  res = http.post(
    `${BASE}/v2/login`,
    JSON.stringify({ username, password, csrf: formCsrf }),
    params({ headers: { 'Content-Type': 'application/json' } })
  );
