  if (res.status === 302) {
    const loc = res.headers['Location'] || res.headers['location'];
    if (loc) {
      const follow = http.get(loc.startsWith('http') ? loc : `${BASE}${loc}`, params());
      check(follow, { 'login redirect ok': (r) => r.status === 200 });
      const fb = parseJson(follow.body);
      if (fb && fb.csrf) csrf = fb.csrf;
      if (fb && fb.grant_id) grant = fb.grant_id;
