  check(res, { 'catalog 200': (r) => r.status === 200 });
  let catalog = parseJson(res.body);
  if (catalog && catalog.csrf) csrf = catalog.csrf;
  let pick = pickInStock(catalog);

  // 5. Traverse /v2/catalog/page up to 3 pages if needed
  let next = catalog && catalog.next;
  let pages = 0;
  while (!pick && next && pages < 3) {
    const url = next.startsWith('http') ? next : `${BASE}${next}`;
    res = http.get(url, params({ headers: { 'X-CSRF-Token': csrf } }));
    check(res, { 'catalog page 200': (r) => r.status === 200 });
    const page = parseJson(res.body);
