  res = http.get(`${BASE}/v2/carts/${cart}`, params({ headers: { 'X-CSRF-Token': csrf } }));
  check(res, { 'cart read 200': (r) => r.status === 200 });
  const readEtag = res.headers['Etag'] || res.headers['ETag'] || res.headers['etag'];
  if (readEtag) etag = readEtag;

  // 8. PATCH quantity with If-Match, retry once on 412
  const patchBody = JSON.stringify({ quantity: 2 });
  const patchHeaders = () => {
    const h = { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf };
    if (etag) h['If-Match'] = etag;
    return h;
  };
  res = http.patch(`${BASE}/v2/carts/${cart}`, patchBody, params({ headers: patchHeaders() }));
  if (res.status === 412) {
    const reread = http.get(`${BASE}/v2/carts/${cart}`, params({ headers: { 'X-CSRF-Token': csrf } }));
    const reEtag = reread.headers['Etag'] || reread.headers['ETag'] || reread.headers['etag'];
    if (reEtag) etag = reEtag;
    res = http.patch(`${BASE}/v2/carts/${cart}`, patchBody, params({ headers: patchHeaders() }));
  }
  check(res, { 'cart patched': (r) => r.status === 200 || r.status === 204 });
  const patchJson = parseJson(res.body);
  if (patchJson && patchJson.csrf) csrf = patchJson.csrf;
  const patchEtag = res.headers['Etag'] || res.headers['ETag'] || res.headers['etag'];
  if (patchEtag) etag = patchEtag;

  // 9. POST /v2/orders with Idempotency-Key = cart
  const orderHeaders = {
    'Content-Type': 'application/json',
    'X-CSRF-Token': csrf,
    'Idempotency-Key': cart,
  };
  if (etag) orderHeaders['If-Match'] = etag;
  res = http.post(
    `${BASE}/v2/orders`,
    JSON.stringify({ cart_id: cart }),
    params({ headers: orderHeaders })
  );
  check(res, { 'order 201': (r) => r.status === 201 });
  const orderJson = parseJson(res.body);
  check(res, { 'order accepted true': () => !!(orderJson && orderJson.accepted === true) });
  if (orderJson && orderJson.csrf) csrf = orderJson.csrf;
}
