};

const BASE = __ENV.BASE_URL || 'http://127.0.0.1:8000';

function jar() {
  return new http.CookieJar();
}

function parseCsrfFromForm(body) {
  if (!body) return null;
  const re = /<input(?=[^>]*\bname=["']csrf["'])(?=[^>]*\bvalue=["']([^"']+)["'])[^>]*>/i;
  const m = body.match(re);
  return m ? m[1] : null;
}

function safeJson(res) {
  try { return res.json(); } catch (e) { return null; }
}

function getHeader(res, name) {
  const h = res.headers[name] || res.headers[name.toLowerCase()];
  return h || null;
}

function isExpired(res) {
  const j = safeJson(res);
  return j && (j.error === 'expired' || j.error === 'session');
}

function isDenied(res) {
  const j = safeJson(res);
  return j && j.error === 'denied';
}

function loginAndGetSession(vu, jarRef) {
  // 1. GET login form
  const formRes = http.get(`${BASE}/v2/login-form`, { jar: jarRef, redirects: 0 });
  check(formRes, { 'login-form 200': (r) => r.status === 200 });
  const formCsrf = parseCsrfFromForm(formRes.body);
  check(formCsrf, { 'login-form csrf extracted': (v) => !!v });

  // 2. POST login (no auto redirect)
  const username = `bench-${vu}`;
  const loginRes = http.post(
    `${BASE}/v2/login`,
    JSON.stringify({ username, password: 'bench', csrf: formCsrf }),
    {
      jar: jarRef,
      redirects: 0,
      headers: { 'Content-Type': 'application/json' },
    }
  );

  let csrf = null;
  let grant = null;

  if (loginRes.status === 302) {
    const location = getHeader(loginRes, 'Location');
    check(location, { 'login Location present': (v) => !!v });
    // Follow dynamic Location exactly once
    const followRes = http.get(location.startsWith('http') ? location : `${BASE}${location}`, {
      jar: jarRef,
      redirects: 0,
    });
    check(followRes, { 'login redirect followed 200': (r) => r.status === 200 });
    const j = safeJson(followRes);
    if (j) {
      csrf = j.csrf || null;
      grant = j.grant_id || null;
    }
  } else {
    check(loginRes, { 'login 200': (r) => r.status === 200 });
    const j = safeJson(loginRes);
    if (j) {
      csrf = j.csrf || null;
      grant = j.grant_id || null;
    }
  }

  check(csrf, { 'session csrf present': (v) => !!v });
  return { csrf, grant };
}

function getCatalogProduct(jarRef) {
  const res = http.get(`${BASE}/v2/catalog`, { jar: jarRef, redirects: 0 });
  check(res, { 'catalog 200': (r) => r.status === 200 });
  const j = safeJson(res);
  if (!j || !j.data || !j.data.products) return null;
  for (const p of j.data.products) {
    if (p.variants && p.variants.length) {
      for (const v of p.variants) {
        if (v.in_stock) {
          return { product: p.id, variant: v.id };
        }
      }
    }
  }
  return null;
}

function createCart(jarRef, csrf, product, variant, grant) {
  const body = { product_id: product, variant_id: variant };
  if (grant) body.grant_id = grant;
  const res = http.post(`${BASE}/v2/carts`, JSON.stringify(body), {
    jar: jarRef,
    redirects: 0,
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
    },
  });
  check(res, { 'cart 201': (r) => r.status === 201 });
  const j = safeJson(res);
  const cartId = j && j.id ? j.id : null;
  const newCsrf = j && j.csrf ? j.csrf : csrf;
  const etag = getHeader(res, 'ETag');
  return { cartId, csrf: newCsrf, etag };
}

function placeOrder(jarRef, csrf, cartId, etag) {
  const headers = {
    'Content-Type': 'application/json',
    'X-CSRF-Token': csrf,
    'Idempotency-Key': cartId,
  };
  if (etag) headers['If-Match'] = etag;
  const res = http.post(
    `${BASE}/v2/orders`,
    JSON.stringify({ cart_id: cartId }),
    { jar: jarRef, redirects: 0, headers }
  );
  check(res, { 'order 201': (r) => r.status === 201 });
  const j = safeJson(res);
  check(j, { 'order accepted true': (v) => v && v.accepted === true });
  return j;
}

export default function () {
  const vu = __VU;
  const jarRef = jar();

  // Fresh login per iteration
  const { csrf: initialCsrf, grant } = loginAndGetSession(vu, jarRef);
  let csrf = initialCsrf;

  // Catalog
  const pick = getCatalogProduct(jarRef);
  check(pick, { 'catalog product picked': (v) => !!v });
  if (!pick) return;

  // Create cart (grant used once)
  const cart = createCart(jarRef, csrf, pick.product, pick.variant, grant);
  check(cart.cartId, { 'cart id present': (v) => !!v });
  if (!cart.cartId) return;
  csrf = cart.csrf;

  // Place order
  placeOrder(jarRef, csrf, cart.cartId, cart.etag);
}
