    const tag = m[0];
    const nameM = tag.match(/\bname\s*=\s*["']([^"']+)["']/i);
    if (!nameM || nameM[1] !== 'csrf') continue;
    const valM = tag.match(/\bvalue\s*=\s*["']([^"']*)["']/i);
    if (valM) return valM[1];
  }
  return null;
}

function parseChallengeForm(body) {
  const actionM = body.match(/<form\b[^>]*\baction\s*=\s*["']([^"']+)["']/i);
  const re = /<input\b[^>]*>/gi;
  let m;
