    const tag = m[0];
    const nameM = tag.match(/\bname\s*=\s*["']([^"']+)["']/i);
    if (!nameM || nameM[1] !== 'challenge') continue;
    const valM = tag.match(/\bvalue\s*=\s*["']([^"']*)["']/i);
    if (valM) challenge = valM[1];
