    'If-Match': etag || '',
  };
  let res = http.patch(`${BASE}/v2/carts/${cartId}`, payload, {
    jar: cj,
    redirects: 0,
    headers,
  });

  if (res.status === 412) {
    const reread = getCart(cj, cartId);
    const newEtag = reread.etag || etag;
    res = http.patch(`${BASE}/v2/carts/${cartId}`, payload, {
      jar: cj,
      redirects: 0,
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': csrf,
        'If-Match': newEtag || '',
      },
    });
    etag = newEtag;
  }

  check(res, { 'patch quantity ok': (r) => r.status === 200 || r.status === 204 });
  const b = jsonBody(res);
  const newCsrf = b && b.csrf ? b.csrf : csrf;
  const newEtag = res.headers['Etag'] || res.headers['ETag'] || res.headers['etag'] || etag;
  return { csrf: newCsrf, etag: newEtag, res };
}

function pollReservation(cj, csrf, cartId) {
  const res = http.post(`${BASE}/v2/reservations`, JSON.stringify({ cart_id: cartId }), {
    jar: cj,
    redirects: 0,
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
  });
  check(res, { 'reservation 202': (r) => r.status === 202 });
  const b = jsonBody(res);
  let statusUrl = b && b.status_url ? b.status_url : null;
  let newCsrf = b && b.csrf ? b.csrf : csrf;
  if (!statusUrl) return { reservationId: null, csrf: newCsrf };

  for (let i = 0; i < 5; i++) {
    const url = statusUrl.startsWith('http') ? statusUrl : `${BASE}${statusUrl}`;
    const sres = http.get(url, { jar: cj, redirects: 0 });
    const sb = jsonBody(sres);
    if (sb) {
      if (sb.csrf) newCsrf = sb.csrf;
      if (sb.status === 'ready' && sb.reservation_id) {
        return { reservationId: sb.reservation_id, csrf: newCsrf };
      }
      if (sb.status === 'failed') {
        return { reservationId: null, csrf: newCsrf };
      }
      if (sb.status_url) statusUrl = sb.status_url;
    }
    // poll at least 50ms apart
    const end = Date.now() + 60;
    while (Date.now() < end) { /* spin */ }
  }
  return { reservationId: null, csrf: newCsrf };
}

function placeOrder(cj, csrf, cartId, etag, reservationId) {
  const payload = { cart_id: cartId };
  if (reservationId) payload.reservation_id = reservationId;
  const idemKey = `idem-${cartId}`;
  const headers = {
    'Content-Type': 'application/json',
    'X-CSRF-Token': csrf,
    'Idempotency-Key': idemKey,
  };
  if (etag) headers['If-Match'] = etag;

  let res = http.post(`${BASE}/v2/orders`, JSON.stringify(payload), {
    jar: cj,
    redirects: 0,
    headers,
  });

  if (res.status === 412) {
    const reread = getCart(cj, cartId);
    if (reread.etag) headers['If-Match'] = reread.etag;
    res = http.post(`${BASE}/v2/orders`, JSON.stringify(payload), {
      jar: cj,
      redirects: 0,
      headers,
    });
  }

  const b = jsonBody(res);
  const accepted = res.status === 201 && b && b.accepted === true;
  check(res, { 'order accepted': () => accepted });
  const newCsrf = b && b.csrf ? b.csrf : csrf;
  return { accepted, csrf: newCsrf, res };
}

export default function () {
  const vu = __VU;
  const row = ACCOUNTS[(vu - 1) % ACCOUNTS.length];
  const cj = jar();

  // Fresh login per iteration
  let csrf = doLogin(cj, row.username, row.password);
  if (!csrf) return;

