function jar() {
  return http.cookieJar();
}

function parseCsrfFromForm(body) {
  if (!body) return null;
  const re = /<input(?=[^>]*\bname=["']csrf["'])(?=[^>]*\bvalue=["']([^"']+)["'])[^>]*>/i;
  const m = body.match(re);
  return m ? m[1] : null;
}

function getHeader(res, name) {
  const h = res.headers[name] || res.headers[name.toLowerCase()];
  return h || null;
}

function isExpired(res) {
  if (res.status !== 401) return false;
  try {
    const b = res.json();
    return b && (b.error === 'expired' || b.error === 'session');
  } catch (e) {
    return false;
  }
}

function isDenied(res) {
  if (res.status !== 401) return false;
  try {
    const b = res.json();
    return b && b.error === 'denied';
  } catch (e) {
    return false;
  }
}

function pickProduct(catalogBody) {
  try {
    const b = JSON.parse(catalogBody);
    const products = (b && b.data && b.data.products) || [];
    for (const p of products) {
      const variants = p.variants || [];
      for (const v of variants) {
        if (v.in_stock) {
          return { product: p.id, variant: v.id };
        }
      }
    }
  } catch (e) {}
  return null;
}

function loginFlow(vu, jarRef) {
  const formRes = http.get(`${BASE}/v2/login-form`, { jar: jarRef, redirects: 0 });
  check(formRes, { 'login-form 200': (r) => r.status === 200 });
  const formCsrf = parseCsrfFromForm(formRes.body);
  check(formCsrf, { 'form csrf present': (v) => !!v });

  const loginRes = http.post(
    `${BASE}/v2/login`,
    JSON.stringify({ username: `bench-${vu}`, password: 'bench', csrf: formCsrf }),
    { jar: jarRef, redirects: 0, headers: { 'Content-Type': 'application/json' } }
  );
  check(loginRes, { 'login ok': (r) => r.status === 200 || r.status === 302 });

  let csrf = null;
  if (loginRes.status === 302) {
    const loc = getHeader(loginRes, 'Location');
    check(loc, { 'login redirect location': (v) => !!v });
    if (loc) {
      const followRes = http.get(loc.startsWith('http') ? loc : `${BASE}${loc}`, {
        jar: jarRef,
        redirects: 0,
      });
      check(followRes, { 'login follow ok': (r) => r.status === 200 });
      try {
        const b = followRes.json();
        csrf = b && b.csrf;
      } catch (e) {}
    }
  } else {
    try {
      const b = loginRes.json();
      csrf = b && b.csrf;
    } catch (e) {}
  }
  check(csrf, { 'login csrf present': (v) => !!v });
  return csrf;
}

function renewSession(jarRef, csrf) {
  const res = http.post(`${BASE}/v2/session/renew`, '{}', {
    jar: jarRef,
    redirects: 0,
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
  });
  let newCsrf = csrf;
  if (res.status === 200) {
    try {
      const b = res.json();
      if (b && b.csrf) newCsrf = b.csrf;
    } catch (e) {}
  }
  return { res, csrf: newCsrf };
}

function recoverCart(jarRef, csrf, cartId) {
  const res = http.post(`${BASE}/v2/carts/${cartId}/recover`, '{}', {
    jar: jarRef,
    redirects: 0,
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
  });
  let newCsrf = csrf;
  if (res.status === 200) {
    try {
      const b = res.json();
      if (b && b.csrf) newCsrf = b.csrf;
    } catch (e) {}
  }
  return { res, csrf: newCsrf };
