function doChallenge(jarRef, csrf) {
  const formRes = http.get(`${BASE}/v2/challenge-form`, { jar: jarRef, redirects: 0 });
  check(formRes, { 'challenge-form 200': (r) => r.status === 200 });
  const body = formRes.body || '';
  const actionMatch = body.match(/action=["']([^"']+)["']/i);
  const challengeMatch = body.match(/<input(?=[^>]*\bname=["']challenge["'])(?=[^>]*\bvalue=["']([^"']+)["'])[^>]*>/i);
  const action = actionMatch ? actionMatch[1] : null;
  const challenge = challengeMatch ? challengeMatch[1] : null;
  check(action, { 'challenge action': (v) => !!v });
  check(challenge, { 'challenge value': (v) => !!v });
  if (!action || !challenge) return { csrf, grant: null };

  const postRes = http.post(
    action.startsWith('http') ? action : `${BASE}${action}`,
    JSON.stringify({ challenge }),
    {
      jar: jarRef,
      redirects: 0,
      headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
    }
  );
  check(postRes, { 'challenge post 302': (r) => r.status === 302 });
  const loc = getHeader(postRes, 'Location');
  check(loc, { 'challenge location': (v) => !!v });
  if (!loc) return { csrf, grant: null };

  const followRes = http.get(loc.startsWith('http') ? loc : `${BASE}${loc}`, {
    jar: jarRef,
    redirects: 0,
  });
  check(followRes, { 'challenge follow 200': (r) => r.status === 200 });
  let newCsrf = csrf;
  let grant = null;
  try {
    const b = followRes.json();
    if (b && b.csrf) newCsrf = b.csrf;
    if (b && b.grant_id) grant = b.grant_id;
  } catch (e) {}
  check(grant, { 'grant present': (v) => !!v });
  return { csrf: newCsrf, grant };
}

function createCart(jarRef, csrf, product, variant, grant) {
  const payload = { product_id: product, variant_id: variant };
  if (grant) payload.grant_id = grant;
  const res = http.post(`${BASE}/v2/carts`, JSON.stringify(payload), {
    jar: jarRef,
    redirects: 0,
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
  });
  let newCsrf = csrf;
  let cartId = null;
  let etag = getHeader(res, 'ETag');
  if (res.status === 201) {
    try {
