    res = http.patch(`${BASE}/v2/carts/${cartId}`, payload, {
      jar: jarRef,
      redirects: 0,
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': newCsrf,
        'If-Match': newEtag || '',
