      if (b && b.csrf) newCsrf = b.csrf;
      if (b && b.status_url) statusUrl = b.status_url;
    } catch (e) {}
  }
  return { res, csrf: newCsrf, statusUrl };
}

function pollReservation(jarRef, csrf, statusUrl) {
  let newCsrf = csrf;
  let reservationId = null;
  let ready = false;
  for (let i = 0; i < 5; i++) {
    if (i > 0) {
      // at least 50ms apart
