  let cart = createCart(jarRef, csrf, picked.product, picked.variant, grant);
  csrf = cart.csrf;
  check(cart.res, { 'cart created 201': (r) => r.status === 201 });
  check(cart.cartId, { 'cart id present': (v) => !!v });
