  let patched = patchCart(jarRef, csrf, cartId, etag, 2);
  csrf = patched.csrf;
  etag = patched.etag;
  check(patched.res, { 'cart patched 200': (r) => r.status === 200 });

  // Reserve
  let resv = reserve(jarRef, csrf, cartId);
  csrf = resv.csrf;
  check(resv.res, { 'reservation 202': (r) => r.status === 202 });
  let reservationId = null;
  if (resv.statusUrl) {
    const polled = pollReservation(jarRef, csrf, resv.statusUrl);
    csrf = polled.csrf;
    if (polled.ready) reservationId = polled.reservationId;
  }

  // Place order with bounded refresh branch
  let order = placeOrder(jarRef, csrf, cartId, etag, reservationId);
  csrf = order.csrf;

  if (isExpired(order.res)) {
    // Bounded refresh: renew, recover cart, retry only the interrupted op once
    const renewed = renewSession(jarRef, csrf);
    csrf = renewed.csrf;
    const recovered = recoverCart(jarRef, csrf, cartId);
    csrf = recovered.csrf;
    order = placeOrder(jarRef, csrf, cartId, etag, reservationId);
    csrf = order.csrf;
  }

  check(order.res, {
    'order 201': (r) => r.status === 201,
    'order accepted true': (r) => {
      try {
        const b = r.json();
        return b && b.accepted === true;
      } catch (e) {
        return false;
      }
    },
  });
}
