function runVU() {
  // login
  const session = login();
  if (!session) return;

  let nextSend = WARMUP_START;
  const vuStart = Date.now();

  while (true) {
    const now = Date.now();
    const elapsed = now - START;
    if (elapsed >= DRAIN_END) break;

    const rate = targetRate(elapsed);
    if (rate <= 0) {
      sleep(0.1);
      continue;
    }

    // per-VU rate = rate / 2
    const perVuRate = rate / 2;
    const interval = 1000 / perVuRate;

    if (now >= nextSend) {
      doWork(session);
      nextSend += interval;
      // if we're behind, catch up but don't burst
      if (nextSend < now) nextSend = now + interval;
    } else {
      sleep(Math.min((nextSend - now) / 1000, 0.05));
    }
  }
}
```

