```js
function expectedSends(elapsed) {
  // cumulative sends expected by elapsed ms, per VU
  // rate schedule: [1000,6000)=5, [6000,16000)=5, [16000,26000)=15, [26000,36000)=5
  // per VU = half
  let total = 0;
  const segments = [
    [1000, 6000, 5],
    [6000, 16000, 5],
    [16000, 26000, 15],
    [26000, 36000, 5],
  ];
  for (const [s, e, r] of segments) {
    if (elapsed <= s) break;
    const end = Math.min(elapsed, e);
    total += (end - s) / 1000 * r / 2;
  }
  return total;
}
```

