import http from 'k6/http';
import { check, sleep } from 'k6';
import { Counter, Rate } from 'k6/metrics';

const BASE = __ENV.BASE_URL || 'http://127.0.0.1:8000';

const workStarts = new Counter('work_starts');
const businessFailures = new Rate('business_failure');

export const options = {
  scenarios: {
    work: {
      executor: 'constant-vus',
      vus: 2,
      duration: '50s',
      gracefulStop: '5s',
    },
  },
  thresholds: {
    'business_failure': ['rate<0.01'],
  },
};

const START = Date.now();

// Schedule (ms since START)
const LOGIN_END = 1000;
const WARMUP_START = 1000;
const SCORED_START = 6000;
const SCORED_END = 36000;
const DRAIN_END = 41000;

function targetRate(elapsed) {
  if (elapsed < WARMUP_START) return 0;
  if (elapsed < SCORED_START) return 5; // warmup
  if (elapsed < SCORED_START + 10000) return 5;
  if (elapsed < SCORED_START + 20000) return 15;
  if (elapsed < SCORED_END) return 5;
  return 0;
}

function expectedSends(elapsed) {
  // cumulative per-VU sends
  let total = 0;
  const segs = [
    [WARMUP_START, SCORED_START, 5],
    [SCORED_START, SCORED_START + 10000, 5],
    [SCORED_START + 10000, SCORED_START + 20000, 15],
    [SCORED_START + 20000, SCORED_END, 5],
  ];
  for (const [s, e, r] of segs) {
    if (elapsed <= s) break;
    const end = Math.min(elapsed, e);
    total += (end - s) / 1000 * r / 2; // per VU = half
  }
  return total;
}

function extractCsrf(html) {
  const re = /<input\b[^>]*\bname\s*=\s*(?:"csrf"|'csrf'|csrf)\b[^>]*>/gi;
  let m;
  while ((m = re.exec(html)) !== null) {
    const tag = m[0];
    const vre = /\bvalue\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+))/i;
    const vm = tag.match(vre);
    if (vm) return vm[1] || vm[2] || vm[3];
  }
  return null;
}

function login(username) {
  const formRes = http.get(`${BASE}/v2/login-form`, { tags: { name: 'login-form' } });
  if (formRes.status !== 200) return null;
  const csrf = extractCsrf(formRes.body);
  if (!csrf) return null;

  const loginRes = http.post(`${BASE}/v2/login`, JSON.stringify({
    username: username,
    password: 'bench',
    csrf: csrf,
  }), {
    headers: { 'Content-Type': 'application/json' },
    tags: { name: 'login' },
    redirects: 0,
  });

  if (loginRes.status === 302) {
    const loc = loginRes.headers['Location'];
    if (loc) {
      const url = loc.startsWith('http') ? loc : `${BASE}${loc}`;
      http.get(url, { tags: { name: 'login-redirect' } });
    }
  }

  let newCsrf = csrf;
  try {
    const body = JSON.parse(loginRes.body);
    if (body.csrf) newCsrf = body.csrf;
  } catch (e) {}

  return { csrf: newCsrf, username: username };
}

function renew(session) {
  const res = http.post(`${BASE}/v2/session/renew`, '{}', {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': session.csrf,
    },
    tags: { name: 'renew' },
  });
  if (res.status === 200) {
    try {
      const body = JSON.parse(res.body);
      if (body.csrf) session.csrf = body.csrf;
    } catch (e) {}
    return true;
  }
  return false;
}

function doWork(session) {
  let retries = 0;
  let renewed = false;
  while (retries <= 4) {
    const res = http.post(`${BASE}/v2/work`, '{}', {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': session.csrf,
      },
      tags: { name: 'work' },
    });

    if (res.status === 429) {
      // scheduled429, retry after Retry-After
      const ra = parseInt(res.headers['Retry-After'] || '1', 10);
      sleep(ra);
      retries++;
      continue;
    }

    if (res.status === 401) {
      // expiry or revoked
      let errType = '';
      try {
        const body = JSON.parse(res.body);
        errType = body.error || '';
      } catch (e) {}

      if (errType === 'denied') {
        businessFailures.add(1);
        return false;
      }

      if (!renewed) {
        renewed = true;
        if (!renew(session)) {
          // re-login
          const s = login(session.username);
          if (!s) { businessFailures.add(1); return false; }
          session.csrf = s.csrf;
        }
        retries++;
        continue;
      }
      businessFailures.add(1);
      return false;
    }

    if (res.status >= 400) {
      businessFailures.add(1);
      return false;
    }

    // success
    try {
      const body = JSON.parse(res.body);
      if (body.csrf) session.csrf = body.csrf;
      if (body.ok === true) {
        workStarts.add(1);
        return true;
      }
    } catch (e) {}
    businessFailures.add(1);
    return false;
  }
  businessFailures.add(1);
  return false;
}

