import http from 'k6/http';
import { check, sleep } from 'k6';
import { Counter, Rate, Trend } from 'k6/metrics';

const BASE = __ENV.BASE_URL || 'http://127.0.0.1:8000';

// Custom metrics
const workSuccess = new Counter('work_success');
const workScheduled429 = new Counter('work_scheduled_429');
const workUnexpected = new Counter('work_unexpected');
const workRawStarts = new Counter('work_raw_starts');
const businessFailure = new Rate('business_failure');
const opDuration = new Trend('op_duration');

export const options = {
  scenarios: {
    flow: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '60s',
      gracefulStop: '5s',
    },
  },
  thresholds: {
    'business_failure': ['rate<0.01'],
  },
  noConnectionReuse: false,
  discardResponseBodies: false,
};

// Per-VU state
let state = {
  cookies: null,
  csrf: null,
  user: null,
  loggedIn: false,
};

function jar() {
  if (!state.cookies) {
    state.cookies = http.cookieJar();
  }
  return state.cookies;
}

function getCsrfFromHtml(body) {
  // input[name=csrf] with possible attribute variants / decoys
  // Match name=csrf (quoted or not) and value
  const re = /<input[^>]*name\s*=\s*["']?csrf["']?[^>]*>/i;
  const m = body.match(re);
  if (!m) return null;
  const tag = m[0];
  const vm = tag.match(/value\s*=\s*["']([^"']*)["']/i);
  return vm ? vm[1] : null;
}

function login() {
  const j = jar();
  // GET login form
  let res = http.get(`${BASE}/v2/login-form`, { jar: j, redirects: 0 });
  if (res.status !== 200) {
    return false;
  }
  const csrf = getCsrfFromHtml(res.body);
  if (!csrf) return false;

  const username = `bench-${__VU}`;
  const payload = JSON.stringify({ username, password: 'bench', csrf });
  res = http.post(`${BASE}/v2/login`, payload, {
    jar: j,
    redirects: 0,
    headers: { 'Content-Type': 'application/json' },
  });

  // Login may return 302 Location
  if (res.status === 302) {
    const loc = res.headers['Location'] || res.headers['location'];
    if (loc) {
      const url = loc.startsWith('http') ? loc : `${BASE}${loc}`;
      res = http.get(url, { jar: j, redirects: 0 });
    }
  }

  if (res.status >= 400) return false;

  let body;
  try { body = JSON.parse(res.body); } catch (e) { return false; }
  if (!body || !body.csrf) return false;

  state.csrf = body.csrf;
  state.user = body.user || username;
  state.loggedIn = true;
  return true;
}

function renew() {
  const j = jar();
  const res = http.post(`${BASE}/v2/session/renew`, '{}', {
    jar: j,
    redirects: 0,
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': state.csrf || '',
    },
  });
  if (res.status >= 400) return false;
  try {
    const body = JSON.parse(res.body);
    if (body && body.csrf) state.csrf = body.csrf;
  } catch (e) { /* retain previous */ }
  return true;
}

function recoverCart(cartId) {
  const j = jar();
  const res = http.post(`${BASE}/v2/carts/${cartId}/recover`, '{}', {
    jar: j,
    redirects: 0,
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': state.csrf || '',
    },
  });
  if (res.status >= 400) return false;
  try {
    const body = JSON.parse(res.body);
    if (body && body.csrf) state.csrf = body.csrf;
  } catch (e) { /* retain */ }
  return true;
}

function parseErr(body) {
  try {
    const b = JSON.parse(body);
    return b && b.error ? b.error : null;
  } catch (e) { return null; }
}

// Perform an authenticated POST with 401 recovery (single retry)
function authPost(path, payload, extraHeaders, cartIdForRecover) {
  const j = jar();
  const headers = Object.assign({
    'Content-Type': 'application/json',
    'X-CSRF-Token': state.csrf || '',
  }, extraHeaders || {});

  let res = http.post(`${BASE}${path}`, payload, { jar: j, redirects: 0, headers });

  if (res.status === 401) {
    const err = parseErr(res.body);
    if (err === 'expired') {
      if (renew()) {
        if (cartIdForRecover) recoverCart(cartIdForRecover);
        headers['X-CSRF-Token'] = state.csrf || '';
        res = http.post(`${BASE}${path}`, payload, { jar: j, redirects: 0, headers });
