    } else if (err === 'session') {
      // revoked: fresh login
      state.loggedIn = false;
      if (login()) {
        if (cartIdForRecover) recoverCart(cartIdForRecover);
        headers['X-CSRF-Token'] = state.csrf || '';
        res = http.post(`${BASE}${path}`, payload, { jar: j, redirects: 0, headers });
      }
    } else if (err === 'denied') {
      // not expiry: fail assertion
      check(res, { 'denied is not expiry': () => false });
    }
  }
  return res;
}

function getCatalog() {
  const j = jar();
  const res = http.get(`${BASE}/v2/catalog`, { jar: j, redirects: 0 });
  if (res.status >= 400) return null;
  try {
    const b = JSON.parse(res.body);
    return b && b.data && b.data.products ? b.data.products : null;
  } catch (e) { return null; }
}

function getCatalogPage(url) {
  const j = jar();
  const full = url.startsWith('http') ? url : `${BASE}${url}`;
  const res = http.get(full, { jar: j, redirects: 0 });
  if (res.status >= 400) return null;
  try {
    return JSON.parse(res.body);
  } catch (e) { return null; }
}

function solveChallenge() {
  const j = jar();
  let res = http.get(`${BASE}/v2/challenge-form`, { jar: j, redirects: 0 });
  if (res.status >= 400) return null;
  const actionM = res.body.match(/action\s*=\s*["']([^"']+)["']/i);
  const chalM = res.body.match(/name\s*=\s*["']?challenge["']?[^>]*value\s*=\s*["']([^"']*)["']/i)
    || res.body.match(/value\s*=\s*["']([^"']*)["'][^>]*name\s*=\s*["']?challenge["']?/i);
  if (!actionM || !chalM) return null;
  const action = actionM[1];
  const challenge = chalM[1];
  const url = action.startsWith('http') ? action : `${BASE}${action}`;
  res = http.post(url, JSON.stringify({ challenge }), {
    jar: j,
    redirects: 0,
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': state.csrf || '',
    },
  });
  if (res.status === 302) {
    const loc = res.headers['Location'] || res.headers['location'];
    if (loc) {
      const lurl = loc.startsWith('http') ? loc : `${BASE}${loc}`;
      res = http.get(lurl, { jar: j, redirects: 0 });
    }
  }
  if (res.status >= 400) return null;
  try {
    const b = JSON.parse(res.body);
    if (b && b.csrf) state.csrf = b.csrf;
    return b && b.grant_id ? b.grant_id : null;
  } catch (e) { return null; }
}

function createCart(productId, variantId, grantId) {
  const j = jar();
  const payload = { product_id: productId, variant_id: variantId };
  if (grantId) payload.grant_id = grantId;
  const res = authPost('/v2/carts', JSON.stringify(payload), {}, null);
  if (res.status !== 201) return null;
  try {
    const b = JSON.parse(res.body);
    if (!b || !b.id) return null;
    if (b.csrf) state.csrf = b.csrf;
    const etag = res.headers['Etag'] || res.headers['ETag'] || res.headers['etag'];
    return { id: b.id, etag };
  } catch (e) { return null; }
}

function patchCart(cartId, etag, quantity) {
  const j = jar();
  const payload = JSON.stringify({ quantity });
  const headers = {
    'Content-Type': 'application/json',
    'X-CSRF-Token': state.csrf || '',
    'If-Match': etag || '',
