    const g = http.get(`${BASE}/v2/carts/${cartId}`, { jar: j, redirects: 0 });
    const newEtag = g.headers['Etag'] || g.headers['ETag'] || g.headers['etag'];
    headers['If-Match'] = newEtag || '';
    res = http.patch(`${BASE}/v2/carts/${cartId}`, payload, { jar: j, redirects: 0, headers });
  }
  if (res.status === 401) {
    const err = parseErr(res.body);
    if (err === 'expired' && renew()) {
      recoverCart(cartId);
      headers['X-CSRF-Token'] = state.csrf || '';
      res = http.patch(`${BASE}/v2/carts/${cartId}`, payload, { jar: j, redirects: 0, headers });
    }
  }
  if (res.status >= 400) return null;
  try {
    const b = JSON.parse(res.body);
    if (b && b.csrf) state.csrf = b.csrf;
  } catch (e) { /* ignore */ }
  return res;
}

function createReservation(cartId) {
  const j = jar();
  const res = authPost('/v2/reservations', JSON.stringify({ cart_id: cartId }), {}, cartId);
  if (res.status !== 202) return null;
  let body;
  try { body = JSON.parse(res.body); } catch (e) { return null; }
  if (body && body.csrf) state.csrf = body.csrf;
