  for (let i = 0; i < 5; i++) {
    sleep(0.06);
    const url = statusUrl.startsWith('http') ? statusUrl : `${BASE}${statusUrl}`;
    const r = http.get(url, { jar: j, redirects: 0 });
    if (r.status >= 400) return null;
    let sb;
    try { sb = JSON.parse(r.body); } catch (e) { return null; }
    if (sb && sb.csrf) state.csrf = sb.csrf;
    if (sb && sb.status === 'ready' && sb.reservation_id) {
      return sb.reservation_id;
    }
    if (sb && (sb.status === 'failed')) return null;
    // pending -> continue
  }
  return null;
}

