    const err = parseErr(res.body);
    if (err === 'expired' && renew()) {
      recoverCart(cartId);
      headers['X-CSRF-Token'] = state.csrf || '';
      res = http.post(`${BASE}/v2/orders`, JSON.stringify(payload), { jar: j, redirects: 0, headers });
    }
  }
  if (res.status !== 201) return false;
  try {
    const b = JSON.parse(res.body);
    if (b && b.csrf) state.csrf = b.csrf;
    return !!(b && b.accepted === true && b.id);
  } catch (e) { return false; }
}

// The scored operation: POST /v2/work with 429 handling
function doWork() {
  const j = jar();
  const maxRetries = 4;
  let attempt = 0;
  while (attempt <= maxRetries) {
    workRawStarts.add(1);
    const headers = {
      'Content-Type': 'application/json',
      'X-CSRF-Token': state.csrf || '',
    };
    const start = Date.now();
    let res = http.post(`${BASE}/v2/work`, '{}', { jar: j, redirects: 0, headers });
    const dur = Date.now() - start;

    if (res.status === 401) {
      const err = parseErr(res.body);
      if (err === 'expired') {
        if (renew()) {
          headers['X-CSRF-Token'] = state.csrf || '';
          workRawStarts.add(1);
          res = http.post(`${BASE}/v2/work`, '{}', { jar: j, redirects: 0, headers });
        }
      } else if (err === 'session') {
        state.loggedIn = false;
        if (login()) {
          headers['X-CSRF-Token'] = state.csrf || '';
          workRawStarts.add(1);
          res = http.post(`${BASE}/v2/work`, '{}', { jar: j, redirects: 0, headers });
        }
      } else if (err === 'denied') {
        check(res, { 'denied not expiry': () => false });
        businessFailure.add(1);
        return false;
      }
    }

    if (res.status === 429) {
      workScheduled429.add(1);
      // honor Retry-After
      let ra = res.headers['Retry-After'] || res.headers['retry-after'];
      let wait = 1;
      if (ra) {
        const n = parseFloat(ra);
        if (!isNaN(n)) wait = n;
      }
      sleep(wait);
      attempt++;
      continue;
    }

    if (res.status >= 400) {
      workUnexpected.add(1);
      businessFailure.add(1);
      return false;
    }

    // success
    let ok = false;
    try {
      const b = JSON.parse(res.body);
      ok = !!(b && b.ok === true);
    } catch (e) { ok = false; }

    if (ok) {
      workSuccess.add(1);
      opDuration.add(dur);
      businessFailure.add(0);
      return true;
    } else {
      workUnexpected.add(1);
      businessFailure.add(1);
      return false;
    }
  }
  // exhausted retries
  workUnexpected.add(1);
  businessFailure.add(1);
  return false;
}

function pickProduct(products) {
  if (!products || !products.length) return null;
  for (const p of products) {
    if (p && p.variants) {
      for (const v of p.variants) {
        if (v && v.in_stock) {
          return { productId: p.id, variantId: v.id };
        }
      }
    }
  }
  return null;
}

function runJourney() {
  // fresh login each journey
  state.loggedIn = false;
  state.csrf = null;
  if (!login()) {
    businessFailure.add(1);
    return;
