```javascript
import http from 'k6/http';
import { check, sleep } from 'k6';
import { Counter, Rate, Trend } from 'k6/metrics';

const BASE = __ENV.BASE_URL || 'http://127.0.0.1:8000';

const workSuccess = new Counter('work_success');
const workScheduled429 = new Counter('work_scheduled_429');
const workUnexpected = new Counter('work_unexpected');
const workRawStarts = new Counter('work_raw_starts');
const businessFailure = new Rate('business_failure');
const opDuration = new Trend('op_duration');

const RAW_CEILING = 12; // per 1s bucket

export const options = {
  scenarios: {
    flow: {
      executor: 'constant-vus',
      vus: 2,
      duration: '40s',
      gracefulStop: '5s',
    },
  },
  thresholds: {
    'business_failure': ['rate<0.01'],
  },
};

let state = { cookies: null, csrf: null, user: null, loggedIn: false };

function jar() {
  if (!state.cookies) state.cookies = http.cookieJar();
  return state.cookies;
}

function getCsrfFromHtml(body) {
  const re = /<input[^>]*name\s*=\s*["']?csrf["']?[^>]*>/i;
  const m = body.match(re);
  if (!m) return null;
  const vm = m[0].match(/value\s*=\s*["']([^"']*)["']/i);
  return vm ? vm[1] : null;
}

function login() {
  const j = jar();
  let res = http.get(`${BASE}/v2/login-form`, { jar: j, redirects: 0 });
  if (res.status !== 200) return false;
  const csrf = getCsrfFromHtml(res.body);
  if (!csrf) return false;
  const username = `bench-${__VU}`;
  res = http.post(`${BASE}/v2/login`, JSON.stringify({ username, password: 'bench', csrf }), {
    jar: j, redirects: 0, headers: { 'Content-Type': 'application/json' },
  });
  if (res.status === 302) {
    const loc = res.headers['Location'] || res.headers['location'];
    if (loc) {
      const url = loc.startsWith('http') ? loc : `${BASE}${loc}`;
      res = http.get(url, { jar: j, redirects: 0 });
    }
  }
  if (res.status >= 400) return false;
  let body;
  try { body = JSON.parse(res.body); } catch (e) { return false; }
  if (!body || !body.csrf) return false;
  state.csrf = body.csrf;
  state.user = body.user || username;
  state.loggedIn = true;
  return true;
}

function renew() {
  const j = jar();
  const res = http.post(`${BASE}/v2/session/renew`, '{}', {
    jar: j, redirects: 0,
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': state.csrf || '' },
  });
  if (res.status >= 400) return false;
  try { const b = JSON.parse(res.body); if (b && b.csrf) state.csrf = b.csrf; } catch (e) {}
  return true;
}

function parseErr(body) {
  try { const b = JSON.parse(body); return b && b.error ? b.error : null; } catch (e) { return null; }
}

// One work attempt with 401 recovery; returns {status, ok, retryAfter}
function workAttempt() {
  const j = jar();
  const headers = { 'Content-Type': 'application/json', 'X-CSRF-Token': state.csrf || '' };
  workRawStarts.add(1);
  const start = Date.now();
  let res = http.post(`${BASE}/v2/work`, '{}', { jar: j, redirects: 0, headers });
  const dur = Date.now() - start;

  if (res.status === 401) {
    const err = parseErr(res.body);
    if (err === 'expired') {
      if (renew()) {
        headers['X-CSRF-Token'] = state.csrf || '';
        workRawStarts.add(1);
        res = http.post(`${BASE}/v2/work`, '{}', { jar: j, redirects: 0, headers });
      }
    } else if (err === 'session') {
      state.loggedIn = false;
      if (login()) {
        headers['X-CSRF-Token'] = state.csrf || '';
        workRawStarts.add(1);
        res = http.post(`${BASE}/v2/work`, '{}', { jar: j, redirects: 0, headers });
      }
    } else if (err === 'denied') {
      check(res, { 'denied not expiry': () => false });
      businessFailure.add(1);
      return { status: 401, ok: false, retryAfter: 0 };
    }
  }

  if (res.status === 429) {
    let ra = res.headers['Retry-After'] || res.headers['retry-after'];
    let wait = 1;
    if (ra) { const n = parseFloat(ra); if (!isNaN(n)) wait = n; }
    return { status: 429, ok: false, retryAfter: wait };
  }

  if (res.status >= 400) {
    workUnexpected.add(1);
    businessFailure.add(1);
    return { status: res.status, ok: false, retryAfter: 0 };
  }

  let ok = false;
  try { const b = JSON.parse(res.body); ok = !!(b && b.ok === true); } catch (e) {}
  if (ok) {
    workSuccess.add(1);
    opDuration.add(dur);
    businessFailure.add(0);
    return { status: 200, ok: true, retryAfter: 0 };
  }
  workUnexpected.add(1);
  businessFailure.add(1);
  return { status: 200, ok: false, retryAfter: 0 };
}

// Phased target rate based on elapsed time since T0
function targetRate(elapsedSec) {
  if (elapsedSec < 0) return 8; // warmup
  if (elapsedSec < 10) return 5;
  if (elapsedSec < 20) return 15;
  if (elapsedSec < 30) return 5;
  return 8; // drain
}

let T0 = null;
let lastStart = 0;
let bucketStart = 0;
let bucketCount = 0;

function paceAndWork() {
  const now = Date.now();
  if (T0 === null) T0 = now;
  const elapsed = (now - T0) / 1000;

  // raw ceiling: track per-1s bucket
  if (now - bucketStart >= 1000) {
    bucketStart = now;
    bucketCount = 0;
  }

  const target = targetRate(elapsed);
  const perVuTarget = target / 2; // 2 VUs
  const intervalMs = 1000 / perVuTarget;

  // pace
  const sinceLast = now - lastStart;
  if (sinceLast < intervalMs) {
    sleep((intervalMs - sinceLast) / 1000);
  }

  // raw ceiling check
  if (bucketCount >= RAW_CEILING) {
    const waitMs = 1000 - (Date.now() - bucketStart);
    if (waitMs > 0) sleep(waitMs / 1000);
    bucketStart = Date.now();
    bucketCount = 0;
  }

  lastStart = Date.now();
  bucketCount++;

  const r = workAttempt();
  if (r.status === 429) {
    workScheduled429.add(1);
    sleep(r.retryAfter);
  }
}

export default function () {
  // ensure logged in
  if (!state.loggedIn) {
    if (!login()) {
      businessFailure.add(1);
      sleep(1);
      return;
    }
  }

  const endTime = Date.now() + 40000;
  while (Date.now() < endTime) {
    paceAndWork();
  }
}
