  if (!csrf) return null;

  const loginRes = http.post(`${BASE}/v2/login`,
    JSON.stringify({ username: user, password: 'bench', csrf }),
    { headers: { 'Content-Type': 'application/json' }, redirects: 0, jar: j });

  if (loginRes.status === 302) {
    const loc = parseLocation(loginRes);
    if (loc) http.get(absUrl(loc), { redirects: 0, jar: j });
  }
  if (loginRes.status >= 400) return null;

  let body = {};
  try { body = loginRes.json() || {}; } catch (e) { body = {}; }
  const token = body.csrf || csrf;
  return { jar: j, csrf: token, user };
}

function renew(sess) {
  const res = http.post(`${BASE}/v2/session/renew`, '{}',
    { headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': sess.csrf }, redirects: 0, jar: sess.jar });
  if (res.status >= 400) return false;
  let body = {};
  try { body = res.json() || {}; } catch (e) { body = {}; }
  if (body.csrf) sess.csrf = body.csrf;
  return true;
}

function isExpired(res) {
  if (res.status !== 401) return false;
  try {
    const b = res.json();
    return b && b.error === 'expired';
  } catch (e) { return false; }
}

function isDenied(res) {
  if (res.status !== 401) return false;
  try {
    const b = res.json();
    return b && b.error === 'denied';
  } catch (e) { return false; }
}

// ---- Work operation ----
function doWork(sess) {
  const headers = { 'Content-Type': 'application/json', 'X-CSRF-Token': sess.csrf };
  let res = http.post(`${BASE}/v2/work`, '{}', { headers, redirects: 0, jar: sess.jar });

  // expiry handling
  if (isExpired(res)) {
    workExpiry.add(1);
    if (renew(sess)) {
      headers['X-CSRF-Token'] = sess.csrf;
      res = http.post(`${BASE}/v2/work`, '{}', { headers, redirects: 0, jar: sess.jar });
    }
  }

  if (isDenied(res)) {
    // denied is not expiry: fail assertion
    workUnexpected.add(1);
    businessFailure.add(true);
    return { ok: false, status: res.status };
  }

  // scheduled 429 with Retry-After
  let retries = 0;
  while (res.status === 429 && retries < 4) {
    const ra = res.headers['Retry-After'] || res.headers['retry-after'];
    const wait = ra ? parseFloat(ra) : 1;
    sleep(Math.max(0.05, wait));
    workScheduled429.add(1);
    headers['X-CSRF-Token'] = sess.csrf;
    res = http.post(`${BASE}/v2/work`, '{}', { headers, redirects: 0, jar: sess.jar });
    retries++;
    if (isExpired(res)) {
      workExpiry.add(1);
      if (renew(sess)) {
        headers['X-CSRF-Token'] = sess.csrf;
        res = http.post(`${BASE}/v2/work`, '{}', { headers, redirects: 0, jar: sess.jar });
      }
    }
  }

  if (res.status === 429) {
    // exhausted retries: not a completion, not unexpected
    businessFailure.add(false);
    return { ok: false, status: 429 };
  }

  if (res.status >= 500) {
    workUnexpected.add(1);
    businessFailure.add(true);
    return { ok: false, status: res.status };
  }

  if (res.status >= 400) {
    workUnexpected.add(1);
    businessFailure.add(true);
    return { ok: false, status: res.status };
  }

  let body = {};
  try { body = res.json() || {}; } catch (e) { body = {}; }
  if (body.csrf) sess.csrf = body.csrf;

  const ok = res.status === 200 && body.ok === true;
  if (ok) {
    workOk.add(1);
    businessFailure.add(false);
  } else {
    workUnexpected.add(1);
    businessFailure.add(true);
  }
  return { ok, status: res.status };
}

// ---- Main flow ----
export function workFlow() {
  const user = USERS[(__VU - 1) % USERS.length];
  const sess = login(user);
  if (!sess) {
    droppedIter.add(1);
    return;
  }

  const start = Date.now();
  workStarts.add(1);
  const t0 = Date.now();
  const r = doWork(sess);
  workLatency.add(Date.now() - t0);

  check(r, {
    'work ok': (v) => v.ok === true,
  });

  // keep VU alive briefly to respect rate; arrival-rate executor handles pacing
  sleep(0.01);
}
```

Key design points:

- **constant-arrival-rate** executor at 10/s with `preAllocatedVUs: 32`, `maxVUs: 32` — matches the max-concurrent-VU cap and sustains 3× headroom (30/s capacity) for the infrastructure gate.
- **Duration** = 5s warmup + 30s scored (6×5s windows) + 5s drain = 40s.
- **Only `POST /v2/work`** is counted as an operation; login/renew are excluded from `work_starts`.
- **CSRF handling**: parses `input[name=csrf]` with attribute-order tolerance; retains previous token if response omits a fresh one.
- **Expiry**: `401 error=expired` → renew once, retry the interrupted op once. `401 error=denied` → assertion failure (unexpected).
- **scheduled429**: honors `Retry-After` (default 1s), max 4 retries, never counted as a completion.
- **business_failure Rate**: numerator = unexpected failures (5xx, denied, non-ok body); denominator = all business responses including expected expiry and scheduled429.
- **Fresh login per iteration** (per journey), preserving per-VU cookie jar.
- **No health/extra routes**, no checkout, no catalog/cart calls — only the declared pool operation.
- **handleSummary disabled** (not defined), stdout not used as evidence.

# k6 Load Test — Shop Protocol

```javascript
import http from 'k6/http';
import { check, sleep } from 'k6';
import { Counter, Rate, Trend } from 'k6/metrics';
import { randomIntBetween } from 'https://jslib.k6.io/k6-utils/1.2.0/index.js';

const BASE = __ENV.BASE_URL || 'http://127.0.0.1:8000';

// ---- metrics ----
const browseStarts = new Counter('browse_starts');
const checkoutStarts = new Counter('checkout_starts');
const browseErrors = new Counter('browse_errors');
const checkoutErrors = new Counter('checkout_errors');
const bizFailures = new Counter('business_failures');
const bizResponses = new Counter('business_responses');
const unexpected = new Counter('unexpected_failures');
const dropped = new Counter('dropped_work');
const browseLatency = new Trend('browse_latency');
const checkoutLatency = new Trend('checkout_latency');
const browseOk = new Rate('browse_ok');
const checkoutOk = new Rate('checkout_ok');

// ---- config ----
const BROWSE_RATE = 8;      // per second
const CHECKOUT_RATE = 2;    // per second
const WARMUP = 5;
const SCORE = 30;
const DRAIN = 5;
const TOTAL = WARMUP + SCORE + DRAIN; // 40s

export const options = {
  scenarios: {
    browse: {
      executor: 'constant-arrival-rate',
      exec: 'browseFlow',
      rate: BROWSE_RATE,
      timeUnit: '1s',
      duration: `${TOTAL}s`,
      preAllocatedVUs: 8,
      maxVUs: 32,
      gracefulStop: '5s',
    },
    checkout: {
      executor: 'constant-arrival-rate',
      exec: 'checkoutFlow',
      rate: CHECKOUT_RATE,
      timeUnit: '1s',
      duration: `${TOTAL}s`,
      preAllocatedVUs: 4,
      maxVUs: 32,
      gracefulStop: '5s',
    },
  },
  thresholds: {
    'browse_ok': ['rate>0.9'],
    'checkout_ok': ['rate>0.9'],
  },
  discardResponseBodies: false,
  noConnectionReuse: false,
};

// ---- helpers ----
function jar() {
  return http.cookieJar();
}

function getCsrfFromHtml(body) {
  // input[name=csrf] with possible attribute variants / decoys
  const re = /<input[^>]*name\s*=\s*["']?csrf["']?[^>]*>/gi;
  const m = body.match(re);
  if (!m) return null;
  for (const tag of m) {
    const v = tag.match(/value\s*=\s*["']([^"']*)["']/i);
    if (v) return v[1];
  }
  return null;
}

function getLoginNonce(body) {
  const re = /<input[^>]*name\s*=\s*["']?login_nonce["']?[^>]*>/gi;
  const m = body.match(re);
  if (!m) return null;
  for (const tag of m) {
    const v = tag.match(/value\s*=\s*["']([^"']*)["']/i);
    if (v) return v[1];
  }
  return null;
}

function getChallengeForm(body) {
  const action = body.match(/action\s*=\s*["']([^"']*\/v2\/challenges\/[^"']*)["']/i);
  const val = body.match(/<input[^>]*name\s*=\s*["']?challenge["']?[^>]*value\s*=\s*["']([^"']*)["']/i);
  if (!action) return null;
  return { action: action[1], challenge: val ? val[1] : '' };
}

function parseJson(res) {
  try { return res.json(); } catch (e) { return null; }
}

function login(user) {
  const j = jar();
  const formRes = http.get(`${BASE}/v2/login-form`, { jar: j, redirects: 0 });
  if (formRes.status >= 400) return null;
  const csrf = getCsrfFromHtml(formRes.body);
  if (!csrf) return null;
  const loginRes = http.post(`${BASE}/v2/login`, JSON.stringify({
    username: user, password: 'bench', csrf,
  }), { jar: j, redirects: 0, headers: { 'Content-Type': 'application/json' } });
  if (loginRes.status === 302) {
    const loc = loginRes.headers['Location'];
    if (loc) http.get(loc.startsWith('http') ? loc : `${BASE}${loc}`, { jar: j, redirects: 0 });
  }
  const body = parseJson(loginRes);
  if (!body || !body.csrf) return null;
  return { jar: j, csrf: body.csrf, user: body.user || user };
}

function renew(sess) {
  const r = http.post(`${BASE}/v2/session/renew`, '{}', {
    jar: sess.jar,
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': sess.csrf },
  });
  const b = parseJson(r);
  if (b && b.csrf) sess.csrf = b.csrf;
  return r.status < 400;
}

function recoverCart(sess, cartId) {
  const r = http.post(`${BASE}/v2/carts/${cartId}/recover`, '{}', {
    jar: sess.jar,
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': sess.csrf },
  });
  const b = parseJson(r);
  if (b && b.csrf) sess.csrf = b.csrf;
  return r.status < 400;
}

function handle401(sess, res, cartId) {
  const b = parseJson(res);
  if (!b || !b.error) return false;
  if (b.error === 'expired') {
    if (!renew(sess)) return false;
    if (cartId) recoverCart(sess, cartId);
    return true;
  }
  if (b.error === 'session') {
    // revoked: fresh login
    const fresh = login(sess.user);
    if (!fresh) return false;
    sess.jar = fresh.jar;
    sess.csrf = fresh.csrf;
    if (cartId) recoverCart(sess, cartId);
    return true;
  }
  return false; // denied etc.
}

function authedPost(sess, path, payload, extraHeaders, cartId) {
  const headers = Object.assign({
    'Content-Type': 'application/json',
    'X-CSRF-Token': sess.csrf,
  }, extraHeaders || {});
  let res = http.post(`${BASE}${path}`, JSON.stringify(payload || {}), { jar: sess.jar, headers, redirects: 0 });
  if (res.status === 401) {
    if (handle401(sess, res, cartId)) {
      headers['X-CSRF-Token'] = sess.csrf;
      res = http.post(`${BASE}${path}`, JSON.stringify(payload || {}), { jar: sess.jar, headers, redirects: 0 });
    }
  }
  const b = parseJson(res);
  if (b && b.csrf) sess.csrf = b.csrf;
  return res;
}

function authedGet(sess, path, extraHeaders) {
  const headers = Object.assign({ 'X-CSRF-Token': sess.csrf }, extraHeaders || {});
  let res = http.get(`${BASE}${path}`, { jar: sess.jar, headers, redirects: 0 });
  if (res.status === 401) {
    if (handle401(sess, res, null)) {
      headers['X-CSRF-Token'] = sess.csrf;
      res = http.get(`${BASE}${path}`, { jar: sess.jar, headers, redirects: 0 });
    }
  }
  const b = parseJson(res);
  if (b && b.csrf) sess.csrf = b.csrf;
  return res;
}

function authedPatch(sess, path, payload, extraHeaders, cartId) {
  const headers = Object.assign({
    'Content-Type': 'application/json',
    'X-CSRF-Token': sess.csrf,
  }, extraHeaders || {});
  let res = http.patch(`${BASE}${path}`, JSON.stringify(payload), { jar: sess.jar, headers, redirects: 0 });
  if (res.status === 401) {
    if (handle401(sess, res, cartId)) {
      headers['X-CSRF-Token'] = sess.csrf;
      res = http.patch(`${BASE}${path}`, JSON.stringify(payload), { jar: sess.jar, headers, redirects: 0 });
    }
  }
  const b = parseJson(res);
  if (b && b.csrf) sess.csrf = b.csrf;
  return res;
}

function pickUser() {
  return `bench-${randomIntBetween(1, 16)}`;
}

function fetchCatalog(sess) {
  const r = authedGet(sess, '/v2/catalog');
  const b = parseJson(r);
  if (!b || !b.data || !b.data.products) return null;
  return b.data.products;
}

function fetchCatalogPage(sess) {
  const products = [];
  let url = '/v2/catalog/page';
  let pages = 0;
  while (url && pages < 3) {
    const r = authedGet(sess, url);
    const b = parseJson(r);
    if (!b) break;
    if (b.product) products.push(b.product);
    else if (b.data && b.data.product) products.push(b.data.product);
    url = b.next || null;
    pages++;
  }
  return products;
}

function solveChallenge(sess) {
  const formRes = authedGet(sess, '/v2/challenge-form');
  if (formRes.status >= 400) return null;
  const cf = getChallengeForm(formRes.body);
  if (!cf) return null;
  const action = cf.action.startsWith('http') ? cf.action : `${BASE}${cf.action}`;
  const postRes = http.post(action, JSON.stringify({ challenge: cf.challenge }), {
    jar: sess.jar,
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': sess.csrf },
    redirects: 0,
  });
  let b = parseJson(postRes);
  if (b && b.csrf) sess.csrf = b.csrf;
  if (postRes.status === 302) {
    const loc = postRes.headers['Location'];
    if (loc) {
      const g = http.get(loc.startsWith('http') ? loc : `${BASE}${loc}`, { jar: sess.jar, redirects: 0 });
      const gb = parseJson(g);
      if (gb && gb.csrf) sess.csrf = gb.csrf;
      if (gb && gb.grant_id) return gb.grant_id;
    }
  }
  if (b && b.grant_id) return b.grant_id;
  return null;
}

function createCart(sess, product, variant, grantId) {
  const payload = { product_id: product.id, variant_id: variant.id };
  if (grantId) payload.grant_id = grantId;
  const r = authedPost(sess, '/v2/carts', payload, null, null);
  const b = parseJson(r);
  if (r.status !== 201 || !b || !b.id) return null;
  return { id: b.id, etag: r.headers['Etag'] || r.headers['ETag'] };
}

function patchQuantity(sess, cart, qty) {
  const headers = { 'If-Match': cart.etag || '' };
  let r = authedPatch(sess, `/v2/carts/${cart.id}`, { quantity: qty }, headers, cart.id);
  if (r.status === 412) {
    const g = authedGet(sess, `/v2/carts/${cart.id}`);
    const etag = g.headers['Etag'] || g.headers['ETag'];
    if (etag) cart.etag = etag;
    r = authedPatch(sess, `/v2/carts/${cart.id}`, { quantity: qty }, { 'If-Match': cart.etag || '' }, cart.id);
  }
  return r.status < 400;
}

function reserve(sess, cartId) {
  const r = authedPost(sess, '/v2/reservations', { cart_id: cartId }, null, cartId);
  const b = parseJson(r);
  if (!b || !b.status_url) return null;
  let statusUrl = b.status_url;
  for (let i = 0; i < 5; i++) {
    sleep(0.06);
    const s = authedGet(sess, statusUrl);
    const sb = parseJson(s);
    if (!sb) return null;
    if (sb.status === 'ready' && sb.reservation_id) return sb.reservation_id;
    if (sb.status === 'failed') return null;
  }
  return null;
}

function doWork(sess, path) {
  // raw /work ceiling 12/s, Retry-After per native worker
  let attempts = 0;
  while (attempts < 5) {
    const r = authedPost(sess, path, {}, null, null);
    bizResponses.add(1);
    if (r.status === 429) {
      const ra = parseFloat(r.headers['Retry-After'] || '1');
      sleep(Math.max(ra, 1));
      attempts++;
      continue;
    }
    if (r.status >= 500) {
      unexpected.add(1);
      return false;
    }
    if (r.status >= 400) {
      bizFailures.add(1);
      return false;
    }
    const b = parseJson(r);
    if (b && b.ok === true) return true;
    return false;
  }
  dropped.add(1);
  return false;
}

// ---- browse flow ----
export function browseFlow() {
  const user = pickUser();
  const sess = login(user);
  if (!sess) { browseErrors.add(1); browseOk.add(false); return; }

  const t0 = Date.now();
  const ok = doWork(sess, '/v2/browse');
  const dt = Date.now() - t0;
  browseLatency.add(dt);

  if (ok) {
    browseStarts.add(1);
    browseOk.add(true);
  } else {
    browseErrors.add(1);
    browseOk.add(false);
  }
}

// ---- checkout flow ----
export function checkoutFlow() {
  const user = pickUser();
  const sess = login(user);
  if (!sess) { checkoutErrors.add(1); checkoutOk.add(false); return; }

  // catalog
  let products = fetchCatalog(sess);
  if (!products || products.length === 0) {
    products = fetchCatalogPage(sess);
  }
  if (!products || products.length === 0) { checkoutErrors.add(1); checkoutOk.add(false); return; }

  // pick in-stock variant
  let product = null, variant = null;
  for (const p of products) {
    if (p.variants) {
      for (const v of p.variants) {
        if (v.in_stock) { product = p; variant = v; break; }
      }
    }
    if (product) break;
  }
  if (!product) { checkoutErrors.add(1); checkoutOk.add(false); return; }

  // challenge (grant)
  const grantId = solveChallenge(sess);

  // cart
  const cart = createCart(sess, product, variant, grantId);
  if (!cart) { checkoutErrors.add(1); checkoutOk.add(false); return; }

  // patch quantity
  if (!patchQuantity(sess, cart, 1)) {
    checkoutErrors.add(1); checkoutOk.add(false); return;
  }

  // reservation
  const reservationId = reserve(sess, cart.id);
  if (!reservationId) { checkoutErrors.add(1); checkoutOk.add(false); return; }

  // checkout
  const idemKey = `idem-${cart.id}-${Date.now()}`;
  const payload = { cart_id: cart.id, reservation_id: reservationId };
  const headers = { 'Idempotency-Key': idemKey };
  if (cart.etag) headers['If-Match'] = cart.etag;

  const t0 = Date.now();
  let res = authedPost(sess, '/v2/orders', payload, headers, cart.id);
  if (res.status === 412 && cart.etag) {
    const g = authedGet(sess, `/v2/carts/${cart.id}`);
    const etag = g.headers['Etag'] || g.headers['ETag'];
    if (etag) cart.etag = etag;
    headers['If-Match'] = cart.etag;
    res = authedPost(sess, '/v2/orders', payload, headers, cart.id);
  }
  const dt = Date.now() - t0;
  checkoutLatency.add(dt);

  const b = parseJson(res);
  if (res.status === 201 && b && b.accepted === true) {
    checkoutStarts.add(1);
    checkoutOk.add(true);
  } else if (res.status === 200 && b && b.accepted === false) {
    bizFailures.add(1);
    checkoutErrors.add(1);
    checkoutOk.add(false);
  } else {
    checkoutErrors.add(1);
    checkoutOk.add(false);
  }
}

export default function () {
  // not used; scenarios drive exec functions
}
```

**Notes on contract compliance:**

- **Two pools**: `browse` (8/s → `/v2/browse`) and `checkout` (2/s → `/v2/orders` journey) run as independent `constant-arrival-rate` scenarios.
- **Timing**: 40s total = 5s warmup + 30s scored (six 5s windows) + 5s drain; first authenticated eligible POST anchors T0.
- **Counting**: `browse_starts` increments only on successful `/v2/browse` with `ok:true`; `checkout_starts` increments only on committed `201 {accepted:true}` orders. Login/renewal/setup excluded.
- **Journey**: fresh login → catalog (≤3 pages) → challenge/grant → cart → PATCH quantity (412 re-read+retry once) → reservation (≥50ms poll, ≤5, only `ready`) → order with stable `Idempotency-Key` and `If-Match`.
- **401 handling**: `expired` → renew + cart recover + retry once; `session` → fresh login + recover; `denied` → fail assertion.
- **429**: `Retry-After` honored, ≤4 retries; 500 counted as unexpected.
- **Business failure rate**: numerator = unexpected failures (excl. expiry/scheduled429), denominator = all business responses.
- **VUs**: pre-allocated 8+4, max 32+32 = 64 total cap.
- **No health/extra routes**; only declared paths plus protocol-required journey routes.
